import { Book } from "@/lib/types";

export const _2kings: Book = {
  id: "2kings",
  name: "2. Könige",
  shortName: "2Kön",
  testament: "old",
  introduction: `Das geteilte Reich in Trümmern\n**Das zweite Buch von den Königen.** Ursprünglich waren beide Königsbücher ein einziges Buch auf einer langen Schriftrolle. Siehe deshalb die Einführung bei 1. Könige!\n****Wie beide Reiche Israels sich zugrunde richten und die Bevölkerung mit Gewalt aus dem Land vertrieben wird.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Nach König Ahabs Tod* sagten sich die Moabiter* von Israel los.", heading: "1-17: Das Nordreich Israel\nEin Prophet in Israel (1-8)\nAhasja und Elija", footnotes: ["Ahabs Tod. Ahab regierte von 874-853 v.Chr.", "Die Moabiter lebten östlich vom Toten Meer in dem Gebiet zwischen den Flüssen Arnon und Zered."] },
      { number: 2, text: "Eines Tages stürzte Ahasja, der neue König, durch das Gitterfenster im Obergeschoss seines Palastes in Samaria und verletzte sich schwer. Da schickte er Boten mit dem Auftrag los, Baal-Sebub*, den Gott der Philisterstadt Ekron zu befragen, ob er wieder gesund würde.", footnotes: ["Baal-Sebub heißt \"Herr der Fliegen\" und ist wahrscheinlich eine bewusste Entstellung von Baal-Sebul \"Fürst Baal\". Bei den Juden in neutestamentlicher Zeit galt Beelzebub als der Oberste der Dämonen."] },
      { number: 3, text: "Aber der Engel Jahwes befahl dem Propheten Elija aus Tischbe*: \"Geh den Boten des Königs von Samaria entgegen und sag zu ihnen: 'Gibt es denn keinen Gott in Israel, dass ihr fortgehen müsst, um den Gott von Ekron, zu befragen?", footnotes: ["Tischbe liegt nach 1. Könige 17,1 im Ostjordanland (Gilead). Die genaue Lage des Ortes ist unbekannt."] },
      { number: 4, text: "Darum lässt Jahwe dem König Folgendes ausrichten: Du wirst nicht mehr aus deinem Bett herauskommen, sondern sterben. Ja, sterben musst du!'\" Elija gehorchte." },
      { number: 5, text: "Da kehrten die Boten zum König zurück. \"Wie kommt es, dass ihr so schnell wieder hier seid?\", fragte er sie." },
      { number: 6, text: "Sie erwiderten: \"Ein Mann kam uns entgegen; er schickte uns zu dir zurück und lässt dir ausrichten: 'So spricht Jahwe: Gibt es denn keinen Gott in Israel, dass du den Baal-Sebub von Ekron befragen musst? Darum wirst du nicht mehr aus deinem Bett herauskommen, sondern sterben. Ja, sterben musst du!'\"" },
      { number: 7, text: "Der König fragte: \"Wie sah der Mann aus, der das zu euch sagte?\"" },
      { number: 8, text: "\"Er trug einen Mantel aus Ziegenhaaren und hatte einen Ledergürtel umgebunden\", erwiderten sie. \"Dann war es Elija von Tischbe\", sagte der König." },
      { number: 9, text: "Sofort schickte er einen Offizier mit fünfzig Mann nach ihm los. Der fand ihn oben auf einem Berg. Er stieg zu ihm hinauf und befahl: \"Im Namen des Königs: Komm herunter, Gottesmann!\"" },
      { number: 10, text: "Elija erwiderte: \"Wenn ich wirklich ein Mann Gottes bin, dann soll Feuer vom Himmel herabfallen und dich und deine fünfzig Mann fressen!\" Da fiel Feuer vom Himmel herab und verbrannte sie alle." },
      { number: 11, text: "Daraufhin schickte der König einen anderen Offizier mit fünfzig Mann los. Auch dieser rief Elija an: \"Im Namen des Königs: Komm sofort herunter, Gottesmann!\"" },
      { number: 12, text: "Doch Elija erwiderte: \"Wenn ich wirklich ein Mann Gottes bin, dann soll Feuer vom Himmel herabfallen und dich und deine fünfzig Mann fressen!\" Da fiel Feuer Gottes vom Himmel herab und verbrannte sie alle." },
      { number: 13, text: "Zum dritten Mal schickte der König einen Offizier mit fünfzig Mann los. Der stieg auf den Berg, kniete sich vor Elija hin und flehte ihn an: \"Du Mann Gottes, lass mich und meine fünfzig Männer am Leben!" },
      { number: 14, text: "Es ist doch Feuer vom Himmel gefallen und hat die beiden Offiziere vor mir und alle ihre Leute vernichtet. Bitte lass mein Leben etwas wert sein vor dir!\"" },
      { number: 15, text: "Da sagte der Engel Jahwes zu Elija: \"Geh mit ihm hinunter! Du musst dich nicht vor dem König fürchten.\"Elija stand auf und ging mit dem Offizier zum König." },
      { number: 16, text: "Er sagte ihm: \"So spricht Jahwe: 'Weil du Boten losgeschickt hast, um den Baal-Sebub, den Gott von Ekron, zu befragen – als ob es keinen Gott in Israel gäbe, den man befragen kann –, darum wirst du nicht mehr aus deinem Bett herauskommen, sondern sterben. Ja, sterben musst du!'\"" },
      { number: 17, text: "So starb er denn, wie Jahwe durch Elija hatte sagen lassen. Weil er aber keinen Sohn hatte, wurde sein Bruder Joram König. Das geschah im zweiten Regierungsjahr von König Joram Ben-Joschafat von Juda." },
      { number: 18, text: "Was sonst noch über Ahasjas Herrschaft zu sagen ist, findet man in der Chronik* der Könige von Israel.", footnotes: ["Chronik. Oder: Jahrbücher, Annalen."] },
    ] },
    { number: 2, verses: [
      { number: 1, text: "An dem Tag, als Jahwe Elija im Sturm zum Himmel auffahren lassen wollte, hatte der Prophet gerade Gilgal* verlassen. Elischa folgte ihm.", heading: "Elija und Elischa", footnotes: ["Mit Gilgal ist hier nicht der Ort in der Nähe des Jordan gemeint, sondern wahrscheinlich Jiljillia, 12 km nordwestlich von Bethel."] },
      { number: 2, text: "Da sagte Elija zu Elischa: \"Bleib doch hier! Denn Jahwe schickt mich nach Bet-El*.\" Doch Elischa erwiderte: \"So wahr Jahwe lebt und so wahr du lebst: Ich verlasse dich nicht!\" So gingen sie nach Bet-El hinab.", footnotes: ["Bet-El liegt 19 km nördlich von Jerusalem und war das Zentrum des pervertierten israelitischen Gottesdienstes, wobei Jahwe durch ein goldenes Kalb verehrt wurde."] },
      { number: 3, text: "Dort wohnten einige Prophetenjünger. Sie kamen zu Elischa heraus und sagten zu ihm: \"Weißt du, dass Jahwe heute deinen Lehrer wegnehmen und zu sich holen wird?\" – \"Ja, ich weiß es auch\", antwortete Elischa, \"redet nicht darüber!\"" },
      { number: 4, text: "Da sagte Elija noch einmal zu ihm: \"Elischa, bleib doch hier! Denn Jahwe schickt mich nach Jericho.\" Doch Elischa erwiderte: \"So wahr Jahwe lebt und so wahr du lebst: Ich verlasse dich nicht!\" So kamen sie nach Jericho." },
      { number: 5, text: "Auch dort wohnten einige Prophetenjünger. Sie kamen ebenfalls zu Elischa heraus und sagten zu ihm: \"Weißt du, dass Jahwe heute deinen Lehrer wegnehmen und zu sich holen wird?\" – \"Ja, ich weiß es auch\", erwiderte Elischa, \"redet nicht darüber!\"" },
      { number: 6, text: "Da sagte Elija noch einmal zu ihm: \"Bleib doch hier! Denn Jahwe schickt mich an den Jordan.\" Doch Elischa erwiderte: \"So wahr Jahwe lebt und so wahr du lebst: Ich verlasse dich nicht!\" So gingen beide miteinander." },
      { number: 7, text: "Auch 50 Mann von den Prophetenjüngern folgten ihnen. Sie blieben aber in einiger Entfernung stehen, als die beiden an den Jordan traten." },
      { number: 8, text: "Elija zog seinen Mantel aus, wickelte ihn zusammen und schlug damit auf das Wasser. Da teilte es sich nach beiden Seiten und sie gingen trockenen Fußes durch den Fluss." },
      { number: 9, text: "Am anderen Ufer sagte Elija zu Elischa: \"Kann ich noch etwas für dich tun, bevor ich weggenommen werde?\" Elischa bat: \"Es wäre schön, wenn ich den doppelten Anteil* von deinem Geist erhalten könnte!\"", footnotes: ["doppelten Anteil. Das meinte wohl den Erbanteil des Erstgeborenen, der doppelt so viel erhielt, wie ein anderer Sohn."] },
      { number: 10, text: "\"Das zu erfüllen, liegt nicht in meiner Macht\", erwiderte Elija, \"doch wenn du mit ansehen darfst, wie ich von dir weggenommen werde, dann wird deine Bitte erfüllt, sonst nicht.\"" },
      { number: 11, text: "Während sie weitergingen und miteinander redeten, fuhr plötzlich ein feuriger Streitwagen mit Pferden aus Feuer zwischen sie und trennte sie voneinander. Im Sturm fuhr Elija zum Himmel hinauf." },
      { number: 12, text: "Als Elischa das sah, schrie er auf: \"Mein Vater, mein Vater! Du Streitwagen Israels, du sein Gespann!\"* Dann sah er ihn nicht mehr. Er packte seine Gewänder und zerriss sie in zwei Stücke.", footnotes: ["sein Gespann. Für Elischa war sein geistlicher Vater das eigentliche Werkzeug der Macht Gottes."] },
      { number: 13, text: "Dann hob er den Mantel Elijas auf, der zu Boden gefallen war, und kehrte an den Jordan zurück." },
      { number: 14, text: "Dort nahm er den Mantel, schlug damit aufs Wasser und rief: \"Wo ist Jahwe, Elijas Gott?\" Als er so wie Elija auf das Wasser geschlagen hatte, teilte es sich nach beiden Seiten, sodass Elischa hindurchgehen konnte." },
      { number: 15, text: "Die Prophetenjünger aus Jericho, die am anderen Ufer standen, hatten zugesehen und sagten: \"Der Geist Elijas ist jetzt auf Elischa!\" Sie liefen ihm entgegen, warfen sich vor ihm nieder" },
      { number: 16, text: "und sagten: \"Bei deinen Dienern hier sind 50 kräftige Männer. Sollten sie nicht losgehen und deinen Lehrer suchen? Vielleicht hat der Geist Jahwes ihn ja nur weggetragen und auf irgendeinen Berg oder in eine Schlucht geworfen.\" – \"Nein, das ist nicht nötig!\", sagte Elischa." },
      { number: 17, text: "Doch sie bestanden heftig darauf bis er verlegen wurde und sagte: \"So geht halt!\" Die 50 suchten drei Tage lang, fanden Elija aber nicht." },
      { number: 18, text: "Dann kehrten sie zu Elischa zurück, der sich noch in Jericho aufhielt. Der sagte zu ihnen: \"Ich habe euch doch gesagt, dass ihr nicht gehen müsst!\"" },
      { number: 19, text: "Die Einwohner der Stadt sagten zu Elischa: \"Herr, wie du siehst, hat unsere Stadt eine ausgezeichnete Lage. Aber das Wasser ist schlecht und verursacht immer wieder Fehlgeburten.\"", heading: "Hilfe in Jericho, Gericht in Bet-El" },
      { number: 20, text: "Da sagte Elischa: \"Holt mir eine neue Schale und füllt sie mit Salz!\" Als sie ihm die Schale gebracht hatten," },
      { number: 21, text: "ging er damit vor die Stadt hinaus zur Quelle, schüttete das Salz hinein und rief: \"So spricht Jahwe: 'Ich habe dieses Wasser gesund gemacht. Es wird keinen Tod und keine Fehlgeburten mehr verursachen!'\"" },
      { number: 22, text: "Seitdem ist das Wasser gut, und es ist bis heute* so geblieben, genau wie Elischa es gesagt hat.", footnotes: ["bis heute. Das meint den Zeitpunkt, als das Buch verfasst wurde."] },
      { number: 23, text: "Von dort aus ging Elischa hinauf ins Bergland nach Bet-El. Wie er nun den Weg weiter hinaufstieg, kam eine Horde Jungen aus der Stadt und machte sich über ihn lustig. \"Komm doch rauf, du Glatzkopf!\", riefen sie. \"Komm doch rauf, Glatzkopf!\"*", footnotes: ["... Glatzkopf. Das drückt eine vollkommene Verachtung dem Repräsentanten Gottes gegenüber aus, den sie wegen seiner Kahlköpfigkeit als Schwächling ansahen. Elischa wurde in dieser Hochburg des von König Jerobeam eingeführten götzendienerischen Jahwekults offenbar nicht nur von den Erwachsenen, sondern auch von den Kindern abgelehnt. Als Nachfolger Elijas würde er diesen falschen Gottesdienst weiterhin bekämpfen."] },
      { number: 24, text: "Elischa schaute sich um und als er sie erblickte, verfluchte er sie im Namen Jahwes. Da kamen zwei Bärinnen aus dem Wald und zerrissen 42 von den Kindern." },
      { number: 25, text: "Elischa ging von dort zum Berg Karmel und kehrte dann nach Samaria zurück." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Im 18. Regierungsjahr des Königs Joschafat von Juda wurde Joram Ben-Ahab König über Israel. Er regierte zwölf Jahre in Samaria", heading: "Joram von Israel" },
      { number: 2, text: "und tat, was Jahwe verabscheute, wenn auch nicht in dem Ausmaß, wie sein Vater und seine Mutter das getan hatten. Er ließ nämlich das Steinmal, das sein Vater zu Ehren des Baal* aufgestellt hatte, wieder beseitigen.", footnotes: ["Baal bedeutet \"Herr\" oder \"Gebieter\". Er wurde als Fruchtbarkeitsgott in Kanaan verehrt."] },
      { number: 3, text: "Doch von dem sündhaften Gottesdienst, zu dem Jerobeam Ben-Nebat Israel verführt hatte, wollte er nicht lassen." },
      { number: 4, text: "König Mescha von Moab war ein Schafzüchter und musste dem König von Israel 100.000 Lämmer und ebenso viele ungeschorene Schafböcke als Tribut* liefern.", footnotes: ["Tribut. Bereits David hatte die Moabiter tributpflichtig gemacht (2. Samuel 8,2). 100 Jahre später waren es dann der mächtigste König des Nordreichs Omri, und sein Sohn Ahab, wie aus der 1868 gefundenen Basaltstele des Königs Mescha hervorgeht: \"Omri war König von Israel und hatte Moab lange Zeit gedemütigt. Und sein Sohn folgte ihm und auch er sprach: 'Ich werde Moab demütigen.'\""] },
      { number: 5, text: "Nach dem Tod Ahabs widersetzte sich Mescha dem König von Israel." },
      { number: 6, text: "Da zog Joram von Samaria aus und rief ganz Israel zu den Waffen." },
      { number: 7, text: "Zugleich sandte er Boten zu König Joschafat von Juda und ließ ihm sagen: \"Der König von Moab ist von mir abgefallen. Willst du zusammen mit mir gegen ihn kämpfen?\" – \"Ich mache mit\", ließ dieser ihm ausrichten, \"du kannst auf meine Soldaten und Pferde wie auf deine eigenen zählen.\"" },
      { number: 8, text: "\"Welchen Weg schlägst du zum Anmarsch vor?\", fragte Joram. \"Den Weg durch die Wüste von Edom\", meldete Joschafat zurück." },
      { number: 9, text: "So rückten der König von Israel und der König von Juda zusammen mit dem König von Edom aus. Als sie sieben Tagereisen weit gezogen waren, fand sich kein Wasser mehr für das Heer und die mitgeführten Tiere." },
      { number: 10, text: "\"Weh uns!\", sagte der König von Israel. \"Jahwe hat uns drei Könige nur gerufen, um uns den Moabitern in die Hände fallen zu lassen!\"" },
      { number: 11, text: "Doch Joschafat sagte: \"Ist denn kein Prophet Jahwes hier, durch den wir Jahwe um Rat fragen könnten?\" Da sagte ein Diener des Königs von Israel: \"Doch, Elischa Ben-Schafat ist hier, der seinerzeit im Dienst Elijas stand.\"" },
      { number: 12, text: "\"Bei ihm werden wir das Wort Jahwes finden\", sagte Joschafat. Da stiegen die drei Könige zu Elischa hinab." },
      { number: 13, text: "Doch der sagte zum König von Israel: \"Was habe ich mit dir zu schaffen? Geh doch zu den Propheten deines Vaters und deiner Mutter!\" – \"Nein\", sagte der König, \"es ist doch Jahwe, der uns drei Könige den Moabitern in die Hände liefern will!\"" },
      { number: 14, text: "Da sagte Elischa: \"So wahr Jahwe, der allmächtige Gott*, lebt, in dessen Dienst ich stehe: Nur König Joschafat von Juda zuliebe sehe ich dich überhaupt an. Sonst wärst du Luft für mich!", footnotes: ["der allmächtige Gott. Hebräisch: Zebaoth, das heißt \"Heere\" oder \"Kriege\". In der LXX wird der Begriff immer mit \"pantokrator\" = \"Allherrscher\" oder \"Allmächtiger\" wiedergegeben."] },
      { number: 15, text: "Doch nun schafft mir einen Harfespieler her!\" Als der Spieler in die Saiten griff, kam die Hand Jahwes über Elischa." },
      { number: 16, text: "Er sagte: \"So spricht Jahwe: 'Hebt in diesem Trockental überall Gruben aus, eine neben der anderen!'" },
      { number: 17, text: "Denn Jahwe sagt: 'Ihr werdet keinen Windhauch spüren und auch keinen Regen fallen sehen, und doch wird sich dieses Tal mit Wasser füllen, sodass ihr mit eurem ganzen Heerlager und den Tieren daraus trinken könnt." },
      { number: 18, text: "Und weil Jahwe das noch nicht genügt, wird er euch auch die Moabiter ausliefern." },
      { number: 19, text: "Ihr werdet alle Festungen und ihre besten Städte erobern, ihr werdet ihre Fruchtbäume fällen, ihre Quellen zuschütten und ihr fruchtbares Ackerland mit Steinen verderben.'\"" },
      { number: 20, text: "Und wirklich, am nächsten Morgen, zur Zeit des Morgenopfers*, kam auf einmal Wasser aus den Bergen Edoms und überschwemmte die ganze Gegend.", footnotes: ["Morgenopfer. Es wurde täglich gegen 10 Uhr im Tempel dargebracht."] },
      { number: 21, text: "Als die Moabiter erfahren hatten, dass drei Könige gegen sie anrückten, wurden alle aufgeboten, die irgend Waffen tragen konnten. Sie stellten sich an der Landesgrenze auf." },
      { number: 22, text: "Als sie an jenem Morgen aufstanden und die Sonne über dem Wasser aufging, erschien ihnen das Wasser im Tal rot wie Blut." },
      { number: 23, text: "\"Das ist Blut!\", sagten sie. \"Ganz sicher sind die Könige mit dem Schwert aneinander geraten und haben ein Blutbad unter sich angerichtet. Auf, ihr Moabiter, holt euch die Beute!\"" },
      { number: 24, text: "Doch als sie zum Lager Israels kamen, stürmten die Israeliten ihnen entgegen und schlugen sie in die Flucht. Dann drang Israel ins Land der Moabiter ein und schlug sie vernichtend." },
      { number: 25, text: "Sie zerstörten die Städte, jeder warf seinen Stein auf jeden Acker, bis alle ganz bedeckt waren. Sie schütteten die Wasserquellen zu und fällten die Fruchtbäume. Nur die Mauer von Kir-Heres* hielt dem Angriff noch stand. Doch die Stadt war umzingelt und wurde mit Steinschleudern beschossen.", footnotes: ["Kir-Heres.Die bedeutende moabitische Stadt lag 16 km östlich vom südlichen Teil des Toten Meeres."] },
      { number: 26, text: "Als der König von Moab sah, dass er die Stadt nicht mehr lange halten konnte, sammelte er 700 Schwertträger um sich und versuchte an der Stelle durchzubrechen, wo der König von Edom stand. Doch es gelang ihnen nicht." },
      { number: 27, text: "Da nahm er seinen erstgeborenen Sohn, der einmal nach ihm König werden sollte, und verbrannte ihn als Opfer auf der Stadtmauer, sodass ein großer Zorn* über Israel kam. Sie brachen die Belagerung ab und kehrten in ihr Land zurück.", footnotes: ["Zorn. Der Ausdruck bezieht sich normalerweise auf den Zorn Gottes. Vielleicht wurde Gott zornig, weil das Kriegsziel längst erreicht war und erst der massive Druck der Verbündeten den moabitischen König zu diesem schrecklichen Menschenopfer für seinen Gott Kemosch getrieben hatte. Andere meinen, dass Zorn hier Abscheu und Entsetzen der Israeliten vor dieser schrecklichen Tat ausdrückt. Schließlich denken einige, dass die Israeliten damals so abergläubisch waren, dass sie sich vor dem Zorn des Moabitergottes fürchteten."] },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Die Witwe von einem der Prophetenjünger rief Elischa um Hilfe an: \"Mein Mann ist gestorben und du weißt, dass er Jahwe treu gedient hat. Nun ist der Gläubiger gekommen und will für das Geld, das wir ihm schulden, meine beiden Söhne als Sklaven nehmen.\"", heading: "Elischa und das Öl der Witwe" },
      { number: 2, text: "Elischa erwiderte: \"Was soll ich für dich tun? Sag mir, was du noch im Haus hast!\" – \"Deine Dienerin hat nichts mehr im Haus als nur ein klein wenig Öl\", erwiderte sie." },
      { number: 3, text: "\"Dann geh und leihe dir von all deinen Nachbarinnen leere Gefäße aus, alles, was du bekommen kannst." },
      { number: 4, text: "Geh dann ins Haus, schließ die Tür hinter dir und deinen Söhnen ab und gieß das Öl in die Gefäße. Wenn eins voll ist, stell es beiseite!\"" },
      { number: 5, text: "Sie machte es so und schloss die Tür ab. Dann reichten die Jungen ihr die Gefäße, und sie goss ein." },
      { number: 6, text: "Als alle Gefäße voll waren, sagte sie zu dem einen Jungen: \"Gib mir noch eins!\" – \"Es ist keins mehr da\", sagte er. Da hörte das Öl auf zu fließen." },
      { number: 7, text: "Die Frau ging zu dem Mann Gottes und berichtete es ihm. Der sagte: \"Nun geh, verkaufe das Öl und bezahle deine Schulden! Von dem, was übrig bleibt, kannst du mit deinen Söhnen leben.\"" },
      { number: 8, text: "Eines Tages kam Elischa durch das Dorf Schunem*. Dort lebte eine wohlhabende Frau, die ihn zum Essen einlud. Von da an war er jedes Mal in ihrem Haus zu Gast, wenn er dort durchkam.", heading: "Elischa und die Frau aus Schunem", footnotes: ["Schunem ist ein Ort in der fruchtbaren Jesreel-Ebene, 15 km östlich von Megiddo am Fuß des Berges More."] },
      { number: 9, text: "Einmal sagte sie zu ihrem Mann: \"Ich weiß, dass unser regelmäßiger Gast ein heiliger Mann Gottes ist." },
      { number: 10, text: "Wir sollten auf der Dachterrasse ein kleines Zimmer für ihn ausbauen und ein Bett, einen Tisch, einen Stuhl und einen Leuchter hineinstellen. Wenn er dann zu uns kommt, kann er sich dorthin zurückziehen.\"" },
      { number: 11, text: "Als Elischa eines Tages wieder vorbeikam, ruhte er sich in diesem Zimmer aus." },
      { number: 12, text: "Dann befahl er seinem Diener Gehasi, die Frau heraufzubitten. Sie kam und blieb draußen vor der Tür stehen." },
      { number: 13, text: "Elischa ließ ihr durch seinen Diener sagen: \"Du hast dir so viel Mühe mit uns gemacht! Was kann man denn für dich tun? Soll man beim König oder beim Heerführer ein gutes Wort für dich einlegen?\" Doch sie sagte: \"Mir geht es gut, ich wohne ja hier mitten unter meiner Sippe.\"" },
      { number: 14, text: "Elischa fragte seinen Diener: \"Was können wir denn sonst für sie tun?\" – \"Nun, die Frau hat keinen Sohn, und ihr Mann ist schon alt\", erwiderte Gehasi." },
      { number: 15, text: "\"Ruf sie her!\", sagte Elischa. Daraufhin kam sie näher und trat in die Tür." },
      { number: 16, text: "\"Im nächsten Jahr um diese Zeit wirst du einen Sohn liebkosen\", sagte Elischa zu ihr. \"Ach Herr, du Mann Gottes\", erwiderte sie, \"mach deiner Magd doch keine falschen Hoffnungen!\"" },
      { number: 17, text: "Doch die Frau wurde wirklich schwanger und brachte ein Jahr später um die Zeit, von der Elischa geredet hatte, einen Sohn zur Welt." },
      { number: 18, text: "Als der Junge größer geworden war, ging er eines Tages zu seinem Vater auf das Feld hinaus, wo die Schnitter arbeiteten." },
      { number: 19, text: "Auf einmal klagte er ihm: \"Mein Kopf! Mein Kopf!\" Der Vater befahl einem seiner Leute: \"Trag ihn zu seiner Mutter!\"" },
      { number: 20, text: "Der Mann brachte das Kind heim. Seine Mutter nahm es auf ihre Knie und hielt es bis zum Mittag, dann starb es." },
      { number: 21, text: "Da trug sie es hinauf und legte es auf das Bett des Gottesmanns. Sie schloss die Tür zu und ging aufs Feld." },
      { number: 22, text: "Dort rief sie ihren Mann und sagte: \"Gib mir einen deiner Männer mit und eine Eselin! Ich muss schnell zu dem Gottesmann und werde bald wieder zurück sein.\"" },
      { number: 23, text: "\"Warum gehst du ausgerechnet heute?\", fragte er. \"Es ist doch weder Neumondstag noch Sabbat.\" – \"Schalom!\"*, sagte sie nur,", footnotes: ["Schalom war der Friedensgruß in Israel und bedeutete gleichzeitig: Es ist alles in Ordnung!"] },
      { number: 24, text: "sattelte die Eselin und befahl dem Diener: \"Treib das Tier tüchtig an, damit wir schnell vorankommen! Halte erst an, wenn ich es dir sage!\"" },
      { number: 25, text: "So kam sie zu dem Gottesmann auf den Berg Karmel. Der sah sie schon von weitem und sagte zu seinem Diener Gehasi: \"Schau an, die Schunemitin!" },
      { number: 26, text: "Lauf ihr entgegen und frage sie, ob es ihr und ihrem Mann und dem Kind gut geht!\" Doch sie sagte nur: \"Schalom!\"" },
      { number: 27, text: "Als sie aber auf dem Berg bei Elischa angekommen war, umklammerte sie seine Füße. Gehasi wollte sie zurückstoßen, doch der Gottesmann sagte: \"Lass sie! Sie ist ja ganz verzweifelt, und Jahwe hat mir nicht gesagt, was geschehen ist.\"" },
      { number: 28, text: "Sie sagte: \"Habe ich dich, mein Herr, denn um einen Sohn gebeten? Habe ich nicht gesagt, du sollst mir keine falschen Hoffnungen machen?\"" },
      { number: 29, text: "Da sagte Elischa zu Gehasi: \"Mach dich fertig, nimm meinen Stab mit und geh so schnell du kannst nach Schunem. Wenn du jemand begegnest, grüße ihn nicht, und wenn dich jemand grüßt, antworte ihm nicht!* Dann halte meinen Stab auf das Gesicht des Jungen!\"", footnotes: ["grüße ... nicht. Das Grüßen war im Orient mit Erkundigungen nach dem gegenseitigen Wohlergehen und dem der Familien verbunden, eine zeitaufwändige Angelegenheit."] },
      { number: 30, text: "Doch die Mutter des Kindes sagte: \"So wahr Jahwe lebt und so wahr du lebst: Ich gehe nicht ohne dich von hier weg!\" Da stand er auf und ging hinter ihr her." },
      { number: 31, text: "Gehasi war vorausgeeilt und hatte den Stab auf das Gesicht des Jungen gehalten. Aber der gab kein Lebenszeichen von sich. Er rührte sich nicht. Da kehrte er um, ging Elischa entgegen und sagte: \"Der Junge ist nicht aufgewacht!\"" },
      { number: 32, text: "Als Elischa ins Haus kam, fand er den Jungen tot auf seinem Bett liegen." },
      { number: 33, text: "Er schloss die Tür hinter sich ab und betete zu Jahwe." },
      { number: 34, text: "Dann legte er sich auf den Jungen, sodass sein Mund dessen Mund berührte, seine Augen vor dessen Augen waren und seine Hände auf dessen Händen lagen. Als er sich so über ihn hinstreckte, erwärmte sich der Körper des Kindes." },
      { number: 35, text: "Dann stand Elischa auf, ging im Zimmer hin und her und legte sich dann wieder auf das Kind. Da nieste der Junge sieben Mal und schlug seine Augen auf." },
      { number: 36, text: "Nun rief Elischa Gehasi und befahl ihm: \"Ruf mir unsere Schunemitin!\" Als sie kam, sagte er zu ihr: \"Hier hast du deinen Sohn!\"" },
      { number: 37, text: "Sie trat heran und warf sich ihm zu Füßen. Dann nahm sie ihren Sohn und verließ das Zimmer." },
      { number: 38, text: "Elischa kehrte nach Gilgal zurück. Im Land herrschte damals Hungersnot. Als die dortigen Prophetenjünger einmal im Unterricht vor ihm saßen, befahl er seinem Diener: \"Setz den großen Topf auf und koche ihnen etwas zu essen!\"", heading: "Elischa und die Hungernden" },
      { number: 39, text: "Da ging einer hinaus aufs Feld, um etwas Essbares zu holen. Dabei fand er ein Rankengewächs mit wilden Kürbissen* und pflückte davon, so viel er in seinem Gewandbausch tragen konnte. Wieder zurück schnitt er sie in Stücke und warf sie in den Topf, obwohl keiner von ihnen die Früchte kannte.", footnotes: ["Der wilde Kürbis (auch Koloquinte genannt) bringt apfelgroße Früchte hervor, die bitter schmecken und drastisch abführend wirken. Heute werden die Früchte als Heilmittel gegen Magenschmerzen verwendet und in der Pharmaindustrie verarbeitet."] },
      { number: 40, text: "Dann teilte man den Männern das Gericht aus. Doch kaum hatten sie davon gegessen, schrien sie auf: \"Mann Gottes, der Tod ist im Topf!\" Sie konnten nichts davon essen." },
      { number: 41, text: "Da sagte Elischa: \"Bringt mir etwas Mehl!\" Er schüttete es in den Topf und sagte zu seinem Diener: \"Teil es jetzt den Leuten zum Essen aus!\" Nun war nichts Schädliches mehr im Topf." },
      { number: 42, text: "Einmal kam ein Mann aus Baal-Schalischa und brachte dem Gottesmann zwanzig Fladenbrote und einen Beutel voll Getreidekörner als Gaben vom ersten Korn der Ernte. Da sagte dieser zu seinem Diener: \"Gib es unseren Leuten zum Essen!\"" },
      { number: 43, text: "Doch der erwiderte: \"Wie soll das für 100 Männer reichen?\" Elischa wiederholte: \"Gib es unseren Leuten zum Essen! Denn so spricht Jahwe: 'Man wird sich satt essen und noch übrig lassen!'\"" },
      { number: 44, text: "Nun setzte er es ihnen vor. Sie aßen sich satt und ließen noch davon übrig, wie Jahwe es gesagt hatte." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Naaman, der Heerführer des Königs von Syrien, wurde von seinem Herrn sehr geschätzt. Auch sonst war er sehr angesehen, denn durch ihn hatte Jahwe den Syrern zum Sieg verholfen. Der Mann war ein Kriegsheld, aber aussätzig.", heading: "Elischa und Naaman" },
      { number: 2, text: "Bei einem ihrer Raubzüge nach Israel hatten die Syrer ein junges Mädchen entführt. Das war als Sklavin zu Naamans Frau gekommen." },
      { number: 3, text: "Einmal sagte sie zu ihrer Herrin: \"Wenn mein Herr doch zu dem Propheten gehen könnte, der in Samaria wohnt! Der würde ihn von seinem Aussatz* heilen*.\"", footnotes: ["Aussatz. Bezeichnung für rasch um sich greifende Hautkrankheiten, Lepra eingeschlossen.", "heilen. Wörtlich: Von seinem Aussatz (weg in die menschliche Gesellschaft wieder) aufnehmen."] },
      { number: 4, text: "Da ging Naaman zu seinem Herrn und berichtete ihm, was die junge Israelitin gesagt hatte." },
      { number: 5, text: "\"Geh doch hin!\", sagte der König*. \"Ich werde dir einen Brief an den König von Israel* mitgeben!\" Da machte sich Naaman auf den Weg. Er nahm 340 Kilogramm Silber mit, 70 Kilogramm Gold* und zehn Festgewänder.", footnotes: ["der König. Das war Ben-Hadad II (860-843 v.Chr.) von Syrien.", "König von Israel. Das war Joram (851-845 v.Chr.).", "... Gold. Maßangaben wörtlich: 10 Talente Silber und 6000 Schekel Gold."] },
      { number: 6, text: "Beim König von Israel angekommen, überreichte er den Brief, in dem es hieß: \"Wenn dieser Brief zu dir kommt, sollst du wissen: Ich habe meinen Diener Naaman zu dir geschickt, damit du ihn vom Aussatz befreist.\"" },
      { number: 7, text: "Als der König von Israel den Brief gelesen hatte, riss er sein Obergewand ein* und rief: \"Bin ich denn Gott, dass ich Macht über Tod und Leben hätte? Verlangt der doch tatsächlich von mir, einen Menschen vom Aussatz zu befreien! Da sieht doch jeder, dass er nur einen Vorwand sucht, um Krieg anzufangen!\"", footnotes: ["riss ... ein. Als Zeichen von Trauer und Entsetzen riss man vom Halsausschnitt an das Kleidungsstück mit einem heftigen Ruck etwa eine Handlänge ein."] },
      { number: 8, text: "Als der Gottesmann Elischa davon hörte, ließ er dem König sagen: \"Warum hast du deine Gewänder eingerissen? Lass ihn doch zu mir kommen! Er soll merken, dass es einen Propheten in Israel gibt!\"" },
      { number: 9, text: "Da fuhr Naaman mit seinen Pferden und Wagen bei Elischa vor." },
      { number: 10, text: "Dieser schickte einen Boten zu ihm hinaus und ließ ihm sagen: \"Fahre an den Jordan und tauche dich sieben Mal darin unter! Dann wird dein Aussatz verschwinden und du wirst gesund sein!\"" },
      { number: 11, text: "Da kehrte Naaman zornig um und sagte: \"Ich hatte gedacht, er würde zu mir herauskommen, sich vor mich hinstellen und den Namen Jahwes, seines Gottes, anrufen. Dabei würde er die Hand über die kranke Stelle schwingen und so den Aussatz verschwinden lassen." },
      { number: 12, text: "Ist denn das Wasser der Flüsse von Damaskus, von Abana und Parpar nicht besser als alle Gewässer Israels?\" So entfernte er sich voller Zorn." },
      { number: 13, text: "Aber seine Diener redeten ihm gut zu: \"Vater\", sagten sie, \"wenn der Prophet etwas Schwieriges von dir verlangt hätte, hättest du es bestimmt getan. Aber nun hat er nur gesagt: 'Bade dich, dann wirst du rein sein!' Solltest du das nicht noch viel eher tun?\"" },
      { number: 14, text: "Da fuhr Naaman doch zum Jordan hinab* und tauchte sieben Mal im Wasser unter, wie es der Gottesmann gesagt hatte. Und tatsächlich wurde seine Haut wieder glatt und rein wie die eines Kindes. Er war gesund.", footnotes: ["Jordan hinab. Von Samaria bis zum Jordan sind es etwa 45 km. Der Jordangraben liegt etwa 300 Meter unter N.N."] },
      { number: 15, text: "Mit seinem ganzen Gefolge kehrte er zu dem Gottesmann zurück. Er trat vor ihn hin und sagte: \"Jetzt weiß ich, dass es auf der ganzen Welt keinen Gott gibt, außer in Israel. Bitte nimm doch ein Geschenk von mir, deinem Diener, an.\"" },
      { number: 16, text: "Doch dieser sagte: \"So wahr Jahwe lebt, vor dem ich stehe: Ich nehme nichts von dir an!\" So sehr er ihm auch zuredete, etwas zu nehmen, er weigerte sich." },
      { number: 17, text: "Da sagte Naaman: \"Wenn du also nichts annimmst, dann gestatte deinen Diener doch, zwei Maultierladungen Erde mitzunehmen. Denn dein Diener wird künftig keinem anderen Gott mehr Opfer* bringen als nur Jahwe.", footnotes: ["Opfer. Wörtlich: Brandopfer oder Schlachtopfer."] },
      { number: 18, text: "Nur das eine möge Jahwe deinem Diener verzeihen: Wenn mein Herr in den Tempel Rimmons* geht, um sich dort niederzuwerfen, dann stützt er sich auf meinen Arm und auch ich muss mich dort mit niederwerfen. Das möge Jahwe mir bitte verzeihen!\"", footnotes: ["Rimmon heißt \"Donnerer\" und war die aramäische (syrische) Gottheit des Sturms und des Krieges und ist auch unter dem Namen Hadad bekannt."] },
      { number: 19, text: "\"Geh in Frieden!\", sagte Elischa.Als sich Naaman schon ein Stück entfernt hatte," },
      { number: 20, text: "sagte sich Elischas Diener Gehasi: \"Mein Herr lässt diesen Syrer ungeschoren davonkommen. Er hätte ihm ruhig etwas von seinen Geschenken abnehmen können. So wahr Jahwe lebt: Ich laufe ihm hinterher und lasse mir etwas von ihm geben!\"" },
      { number: 21, text: "So rannte Gehasi Naaman nach. Als dieser sah, dass ihm jemand nachlief, sprang er vom Wagen ab, ging ihm entgegen und sagte: \"Ist alles in Ordnung?\"" },
      { number: 22, text: "\"Ja\", sagte dieser, \"aber mein Herr lässt dir sagen: 'Eben sind zwei junge Prophetenjünger aus dem Bergland von Efraïm zu mir gekommen. Gib mir doch ein Talent Silber* und zwei Festgewänder für sie!\"", footnotes: ["ein Talent Silber. Das sind Silberstücke im Gewicht von 34 Kilogramm."] },
      { number: 23, text: "\"Ich bitte dich, nimm zwei Talente!\", erwiderte Naaman. Er packte die 68 Kilogramm Silberstücke in zwei Beutel, legte die beiden Festgewänder dazu und schickte zwei seiner Leute mit, die das Geschenk vor Gehasi hertragen sollten." },
      { number: 24, text: "Als sie an den Stadthügel* kamen, schickte Gehasi die beiden Männer zurück und versteckte die Geschenke im Haus.", footnotes: ["Stadthügel. Der Hügel, auf dem die Stadt Samaria gebaut war, erhob sich etwa 100 Meter über das Umland."] },
      { number: 25, text: "Er ging dann wieder zu seinem Herrn. Da fragte ihn Elischa: \"Woher kommst du, Gehasi?\" – \"Dein Diener war doch die ganze Zeit hier!\", erwiderte er." },
      { number: 26, text: "Aber Elischa entgegnete ihm: \"Bin ich nicht im Geist mit dir gegangen, als der Mann von seinem Wagen stieg und dir entgegenkam? Ist es jetzt an der Zeit, Geld und Festkleider anzunehmen und davon Olivenhaine und Weinberge, Schafe und Rinder, Sklaven und Sklavinnen zu kaufen?" },
      { number: 27, text: "Der Aussatz Naamans wird dich und alle deine Nachkommen für immer befallen.\" Als Gehasi ihn verließ, war er vom Aussatz weiß wie Schnee." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Einst sagten die Prophetenjünger zu Elischa: \"Der Unterrichtsraum ist zu eng für uns geworden.", heading: "Elischa und die Axt" },
      { number: 2, text: "Könnten wir nicht an den Jordan gehen, damit jeder von uns einen Balken heranschafft und wir hier einen neuen Versammlungsraum bauen können?\" – \"Geht nur!\", sagte Elischa." },
      { number: 3, text: "Aber einer der Männer sagte: \"Tu uns doch den Gefallen und komm mit!\" – \"Gut, ich komme mit\", erwiderte er." },
      { number: 4, text: "So gingen sie miteinander an den Jordan und begannen Bäume zu fällen." },
      { number: 5, text: "Bei der Arbeit rutschte einem das Eisen vom Stiel und fiel ins Wasser. \"O weh!\", schrie er und sagte zu Elischa: \"Mein Herr, die Axt war auch noch geliehen!\"" },
      { number: 6, text: "Der Gottesmann fragte ihn: \"Wohin ist es denn gefallen?\" Er zeigte ihm die Stelle. Darauf schnitt sich Elischa ein Stück Holz ab, warf es dort ins Wasser und brachte so das Eisen zum Schwimmen." },
      { number: 7, text: "\"Hol es dir heraus!\", sagte er. Der Mann bückte sich und nahm es." },
      { number: 8, text: "Der König von Syrien kämpfte immer wieder gegen Israel. Er beriet sich mit seinen Truppenführern und sagte: \"Da und da legt einen Hinterhalt!\"", heading: "Elischa und die Syrer" },
      { number: 9, text: "Aber der Gottesmann ließ dem König von Israel sagen: \"Zieh nicht an dieser Stelle vorbei, denn dort wollen die Syrer dich angreifen!\"" },
      { number: 10, text: "Daraufhin ließ der König von Israel die Gegend auskundschaften, vor der ihn der Gottesmann gewarnt hatte, und war dort besonders vorsichtig. Das passierte nicht nur ein oder zwei Mal." },
      { number: 11, text: "Den König von Syrien beunruhigte die Sache sehr. Er ließ seine Truppenführer kommen und sagte: \"Könnt ihr mir nicht sagen, wer von den Unsern zum König von Israel hält?\"" },
      { number: 12, text: "\"Nein, mein Herr und König\", sagte einer von ihnen, \"es ist der Prophet Elischa. Der meldet seinem König sogar das, was du in deinem Schlafzimmer sagst.\"" },
      { number: 13, text: "Da befahl der König: \"Findet heraus, wo er ist! Dann werde ich ihn mir schon holen.\" Man meldete ihm: \"Er ist in Dotan*.\"", footnotes: ["Die Stadt Dotan lag auf einem Hügel in der Jesreel-Ebene, 18 km nördlich von Samaria."] },
      { number: 14, text: "Da schickte er ein ganzes Heer dorthin mit Pferden und Streitwagen, eine starke Truppe. Sie rückten bei Nacht an und umzingelten die Stadt." },
      { number: 15, text: "Als der Diener des Gottesmannes früh am Morgen aufstand, sah er die Stadt plötzlich von einem Heer, von Pferden und Streitwagen umringt. \"Ach, mein Herr, was sollen wir jetzt machen?\", rief er." },
      { number: 16, text: "Doch dieser sagte: \"Hab keine Angst, denn auf unserer Seite stehen viel mehr als bei ihnen.\"" },
      { number: 17, text: "Dann betete Elischa: \"Jahwe, öffne ihm doch die Augen!\" Da öffnete Jahwe die Augen des Dieners, und er sah auf einmal, dass der ganze Berg rings um Elischa von Pferden und Streitwagen aus Feuer wimmelte." },
      { number: 18, text: "Als dann die Syrer anrückten, betete Elischa: \"Schlag sie doch mit Blindheit!\" Jahwe tat, was Elischa erbeten hatte, und machte sie blind." },
      { number: 19, text: "Elischa ging ihnen entgegen und sagte: \"Das ist nicht der Weg und auch nicht die richtige Stadt. Folgt mir! Ich bringe euch zu dem Mann, den ihr sucht.\" Er führte sie nach Samaria." },
      { number: 20, text: "Als sie dort angekommen waren, betete Elischa: \"Jahwe, öffne ihnen wieder die Augen!\" Da öffnete Jahwe ihre Augen und sie erkannten, dass sie sich mitten in der Stadt Samaria befanden." },
      { number: 21, text: "Als der König von Israel sie sah, fragte er Elischa: \"Soll ich losschlagen, mein Vater? Soll ich sie erschlagen?\"" },
      { number: 22, text: "\"Nein, das sollst du nicht!\", erwiderte dieser. \"Du würdest doch auch niemand erschlagen, den du mit Schwert und Bogen gefangen genommen hast! Gib ihnen lieber etwas zu essen und zu trinken und lass sie dann zu ihrem Herrn ziehen!\"" },
      { number: 23, text: "Da ließ der König ein reiches Mahl für sie bereiten. Sie aßen und tranken und durften dann wieder zu ihrem Herrn zurückkehren. Seitdem unternahmen die Syrer keine Raubzüge mehr in das Gebiet Israels." },
      { number: 24, text: "Einige Zeit später mobilisierte der syrische König Ben-Hadad* sein ganzes Heer und belagerte Samaria.", heading: "Elischa im belagerten Samaria", footnotes: ["Ben-Hadad II. regierte von etwa 860-843 v.Chr. Die Belagerung Samarias fand wahrscheinlich um 844 v.Chr. statt."] },
      { number: 25, text: "In der Stadt kam es dadurch zu einer schweren Hungersnot, sodass ein Eselskopf schließlich 80 Silberstücke* kostete und ein drittel Liter* Taubendreck* fünf Silberstücke.", footnotes: ["80 Siberstücke. Das war etwa 1 Kilogramm Silber.", "ein drittel Liter. Hebräisch: 1/4 Kab. 1Kab = 1/18 Efa = 1,2 Liter.", "Taubendreck.Wahrscheinlich Bezeichnung für ein ganz minderwertiges Nahrungsmittel."] },
      { number: 26, text: "Als der König eines Tages auf der Stadtmauer entlangging, schrie eine Frau zu ihm hoch: \"Hilf mir, mein Herr und König!\"" },
      { number: 27, text: "Doch er erwiderte: \"Wenn dir Jahwe nicht hilft, wie soll ich dir dann helfen – vielleicht mit etwas Getreide oder Traubensaft?\"" },
      { number: 28, text: "Dann fragte der König: \"Was hast du?\" Sie erwiderte: \"Diese Frau dort hat zu mir gesagt: 'Gib deinen Sohn her, den essen wir heute! Morgen essen wir dann meinen Sohn.'" },
      { number: 29, text: "So haben wir also meinen Sohn gekocht und aufgegessen. Als ich aber am nächsten Tag zu ihr sagte: 'Nun gib deinen Sohn her, wir wollen ihn essen!', da hatte sie ihn versteckt.\"" },
      { number: 30, text: "Als der König das hörte, riss er sein Obergewand ein. Und weil er oben auf der Mauer stand, konnten alle sehen, dass er darunter den Trauersack auf dem bloßen Leib trug." },
      { number: 31, text: "Da schwor er: \"Gott soll mich strafen, wenn Elischa Ben-Schafat heute seinen Kopf behält!\"" },
      { number: 32, text: "Elischa saß gerade in seinem Haus zusammen mit den Ältesten der Stadt. Der König hatte einen Mann vorausgeschickt. Und noch bevor der Bote zu ihm kam, sagte Elischa zu den Ältesten: \"Seht ihr, wie dieser Mördersohn jemand hergeschickt hat, der mir den Kopf abschlagen soll? Passt auf! Wenn der Bote kommt, verschließt die Tür und stemmt euch dagegen, denn ich höre schon die Fußtritte seines Herrn hinter ihm!\"" },
      { number: 33, text: "Elischa redete noch mit ihnen, da war der König schon bei ihm und rief: \"Seht doch, Jahwe hat uns alle ins Unglück gestürzt! Was soll ich noch länger auf seine Hilfe warten!\"" },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Da sagte Elischa: \"Hört das Wort Jahwes! So spricht Jahwe: 'Morgen um diese Zeit werden im Tor von Samaria ein Eimer* voll Feinmehl und zwei Eimer voll Gerste für ein Silberstück zu kaufen sein.'\"", footnotes: ["Eimer. Hebräisch: Sea. 1 Sea = 7,3 Liter."] },
      { number: 2, text: "Der Adjutant des Königs erwiderte: \"Selbst wenn Jahwe Schleusen am Himmel anbringen würde – das ist unmöglich!\" Elischa entgegnete: \"Pass auf! Du wirst es mit eigenen Augen sehen, aber nicht mehr davon essen.\"" },
      { number: 3, text: "Nun gab es da vier aussätzige Männer, die draußen vor dem Stadttor saßen. Sie sagten zueinander: \"Sollen wir hier sitzen bleiben bis wir sterben?" },
      { number: 4, text: "Wenn wir in die Stadt gehen, verhungern wir auch nur. Bleiben wir hier, sterben wir ebenfalls. Kommt, wir gehen ins Lager der Syrer! Wenn sie uns am Leben lassen, leben wir, und wenn sie uns töten, sterben wir eben.\"" },
      { number: 5, text: "So gingen sie bei Anbruch der Dunkelheit ins Lager der Syrer. Schon am Rand merkten sie, dass das Lager verlassen war." },
      { number: 6, text: "Denn der Herr hatte die Syrer ein Getöse von Wagen und Pferden hören lassen, das wie der Lärm eines großen Heeres klang. Da hatten sie sich gesagt: \"Seht, der König von Israel hat die Könige der Hetiter* und Ägypter angeworben, dass sie uns jetzt überfallen!\"", footnotes: ["Könige der Hetiter.Könige verschiedener Stadtstaaten, die im Norden Syriens nach dem Zerfall des Hetitischen Reichs um 1200 v.Chr. entstanden waren."] },
      { number: 7, text: "So hatten sie bei Anbruch der Dunkelheit die Flucht ergriffen und waren um ihr Leben gelaufen. Ihre Zelte, ihre Pferde, ihre Esel und das ganze Lager hatten sie zurückgelassen, wie es war." },
      { number: 8, text: "Die Aussätzigen gingen nun in eins der Zelte, aßen und tranken, nahmen Silber, Gold und Gewänder mit und versteckten alles. Dann gingen sie in ein anderes Zelt und nahmen auch von dort etwas mit und versteckten es." },
      { number: 9, text: "Doch dann sagten sie zueinander: \"Es ist nicht richtig, was wir machen. Heute ist ein Tag guter Botschaft. Wenn wir das auch nur bis morgen für uns behalten, machen wir uns schuldig. Lasst uns in die Stadt zum Palast des Königs gehen und dort melden, was passiert ist!\"" },
      { number: 10, text: "So liefen sie zur Stadt, riefen die Torwächter an und berichteten ihnen: \"Wir sind im Lager der Syrer gewesen und haben dort keinen Menschen mehr gefunden und auch keine Menschenstimme gehört. Wir fanden nur Pferde und Esel angebunden und die Zelte so stehen, wie sie waren.\"" },
      { number: 11, text: "Die Torwächter meldeten es im Palast des Königs." },
      { number: 12, text: "Obwohl es mitten in der Nacht war, stand der König auf und beriet sich mit seinen Offizieren. \"Ich will euch sagen, was die Syrer vorhaben\", begann der König. \"Weil sie wissen, dass wir am Verhungern sind, haben sie das Lager verlassen und sich im Gelände versteckt. Sie haben gedacht: 'Wenn die aus der Stadt herauskommen, werden wir sie lebendig fangen und in die Stadt eindringen!'\"" },
      { number: 13, text: "Da schlug einer der Offiziere vor: \"Wir könnten doch fünf unserer letzten Pferde anspannen und nachsehen lassen. Es wird ihnen ja doch nicht anders ergehen als dem Rest der Israeliten, die ohnehin am Ende sind.\"" },
      { number: 14, text: "Der König ließ also zwei Streitwagen anspannen und sagte den Männern: \"Fahrt hin und seht nach!\"" },
      { number: 15, text: "Sie verfolgten die Spur des Heeres bis an den Jordan. Der ganze Weg war mit Kleidungsstücken und Waffen übersät, die die Syrer auf der hastigen Flucht weggeworfen hatten.Als die Boten zurückgekehrt waren und dem König Bericht erstattet hatten," },
      { number: 16, text: "stürmte das ganze Volk aus der Stadt hinaus und plünderte das Lager der Syrer. Und nun kosteten ein Eimer Feinmehl und zwei Eimer Gerste tatsächlich nur noch ein Silberstück, wie Jahwe es angekündigt hatte." },
      { number: 17, text: "Der König hatte seinem Adjutanten die Aufsicht über das Tor übertragen. Doch das Volk trampelte ihn zu Tode, so wie der Gottesmann es ihm gesagt hatte, als der König in sein Haus gekommen war." },
      { number: 18, text: "Denn als Elischa dem König gesagt hatte: \"Morgen um diese Zeit werden im Tor von Samaria ein Eimer Feinmehl und zwei Eimer Gerste für ein Silberstück zu kaufen sein\"," },
      { number: 19, text: "hatte der Adjutant entgegnet: \"Selbst wenn Jahwe Schleusen am Himmel anbringen würde – das ist unmöglich!\" Darauf hatte Elischa ihm erwidert: \"Pass auf! Du wirst es mit eigenen Augen sehen, aber nicht mehr davon essen.\"" },
      { number: 20, text: "Genauso kam es: Das Volk trampelte ihn im Tordurchgang zu Tode." },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Elischa hatte der Frau, deren Sohn er wieder lebendig gemacht hatte, den Rat gegeben: \"Zieh mit deiner ganzen Familie von hier weg und bleib irgendwo im Ausland! Denn Jahwe hat eine siebenjährige Hungersnot über das Land verhängt.\"", heading: "Elischa und die Frau aus Schunem (Fortsetzung)" },
      { number: 2, text: "Die Frau hatte den Rat des Gottesmannes befolgt und war mit ihren Angehörigen ins Land der Philister gezogen." },
      { number: 3, text: "Als die sieben Jahre vorüber waren, kehrte sie nach Israel zurück und wandte sich an den König, um ihr Haus und ihre Ländereien zurück zu bekommen." },
      { number: 4, text: "Der König hatte gerade mit Gehasi*, dem Diener des Gottesmannes, gesprochen und ihn gebeten, all die großen Taten Elischas zu erzählen.", footnotes: ["mit Gehasi. Offenbar geschah dies alles noch vor der Heilung Naamans, denn Gehasi war noch nicht aussätzig. Sonst hätte er nicht vor dem König erscheinen dürfen."] },
      { number: 5, text: "Und gerade, als er erzählte, wie Elischa den Toten lebendig gemacht hatte, erschien die Frau vor dem König und rief ihn um Hilfe wegen ihres Hauses und ihrer Ländereien an. Da sagte Gehasi: \"Das ist die Frau und auch der Sohn, den Elischa wieder lebendig gemacht hat.\"" },
      { number: 6, text: "Der König ließ sich alles noch einmal von der Frau selbst erzählen. Dann gab er ihr einen Hofbeamten mit und befahl ihm: \"Gib ihr alles zurück, was ihr gehört. Erstatte ihr auch den Ertrag, den ihr Land in den Jahren ihrer Abwesenheit hervorgebracht hat.\"" },
      { number: 7, text: "Einmal kam Elischa nach Damaskus. Ben-Hadad, der König von Syrien, war gerade krank.* Als er erfuhr, dass der Gottesmann in der Stadt sei,", heading: "Elischa und Hasaël von Damaskus", footnotes: ["gerade krank. Dieses Geschehen ist zeitlich wohl nach der Heilung Naamans einzuordnen und nach dem Sieg des Assyrerkönigs Salmanasser III. über Ben-Hadad 846 v.Chr., also etwa um das Jahr 843 v.Chr."] },
      { number: 8, text: "befahl er Hasaël: \"Nimm Geschenke mit, geh zu dem Mann Gottes und frag Jahwe durch ihn, ob ich wieder gesund werde.\"" },
      { number: 9, text: "Hasaël ließ vierzig Kamele mit Kostbarkeiten aus Damaskus beladen und kam damit zu Elischa. Er sagte: \"Dein Sohn* Ben-Hadad, der König von Syrien, schickt mich zu dir und lässt fragen, ob er wieder gesund wird.\"", footnotes: ["Sohn drückt hier kein Verwandtschaftsverhältnis aus, sondern ist eine ehrerbietige Anrede, siehe 6,21."] },
      { number: 10, text: "Elischa sagte zu ihm: \"Richte ihm aus: 'Ja, du wirst wieder gesund.' Aber Jahwe hat mich sehen lassen, dass er sterben muss.\"*", footnotes: ["sterben muss. Die Krankheit würde er überwinden können, aber er muss eines unnatürlichen Todes sterben."] },
      { number: 11, text: "Bei diesen Worten wurde sein Gesicht starr vor Entsetzen. Dann brach der Gottesmann in Tränen aus." },
      { number: 12, text: "\"Warum weinst du, mein Herr?\", fragte Hasaël. \"Weil ich erkannt habe, wie viel Böses du über die Israeliten bringen wirst. Du wirst ihre festen Städte in Brand stecken, ihre jungen Männer mit dem Schwert erschlagen, ihre Kinder am Boden zerschmettern und Schwangeren den Leib aufschlitzen.\"" },
      { number: 13, text: "\"Aber dein Diener ist doch nur ein armer Hund\", erwiderte Hasaël, \"wie sollte der etwas so Gewaltiges zustande bringen?\" Elischa sagte: \"Jahwe hat mich wissen lassen, dass du König über Syrien wirst.\"" },
      { number: 14, text: "Dann kehrte Hasaël zu seinem Herrn zurück. Der fragte ihn: \"Was hat Elischa dir gesagt?\" – \"Er hat gesagt: 'Ja, du wirst wieder gesund'\", erwiderte er." },
      { number: 15, text: "Am folgenden Tag nahm er eine Decke, tauchte sie in Wasser und breitete sie so über das Gesicht des Königs aus, dass er starb. Und Hasaël wurde an seiner Stelle König." },
      { number: 16, text: "Im fünften Regierungsjahr von Joram Ben-Ahab, dem König von Israel, trat Joram Ben-Joschafat, der bis dahin nur Mitregent* war, die Herrschaft über Juda an.", heading: "Joram von Juda", footnotes: ["Mitregent. 853 v.Chr., bevor Joschafat mit Ahab in den Krieg gegen Ramot zog, macht er seinen Sohn Joram zum Mitregenten. Erst 848 v.Chr. begann dessen Alleinherrschaft über Juda."] },
      { number: 17, text: "Er war damals 32 Jahre alt und regierte acht Jahre* in Jerusalem.", footnotes: ["acht Jahre. Von 848-841 v.Chr."] },
      { number: 18, text: "Wie die Familie Ahabs folgte er dem bösen Beispiel der Könige von Israel und tat, was Jahwe verabscheute. Seine Frau war nämlich eine Tochter Ahabs." },
      { number: 19, text: "Doch Jahwe wollte Juda nicht vernichten, hatte er doch seinem Diener David versprochen, dass er auch in Zukunft stets einen Nachkommen haben würde." },
      { number: 20, text: "In dieser Zeit rebellierten die Edomiter gegen die Oberherrschaft Judas und setzten einen eigenen König ein." },
      { number: 21, text: "Daraufhin zog Joram mit all seinen Streitwagen bis in die Gegend von Zaïr*. Doch die Edomiter schlossen ihn und die Offiziere seiner Streitwagen ein. Da schlug er in der Nacht los und durchbrach den Ring. Sein Heer floh nach Hause zurück.", footnotes: ["Die Lage von Zaïr ist nicht bekannt; vermutlich eine Stadt in Edom."] },
      { number: 22, text: "Bis heute blieb Edom unabhängig von Juda. Damals sagte sich auch die Stadt Libna* von Judas Herrschaft los.", footnotes: ["Libna war als Levitenstadt dem Stamm Juda zugeteilt worden und lag 32 km südwestlich von Jerusalem."] },
      { number: 23, text: "Was es sonst noch über Jorams Herrschaft zu berichten gibt, steht in der Chronik der Könige von Juda." },
      { number: 24, text: "Nach seinem Tod wurde er in der Grabstätte der Königsfamilie in der Davidsstadt* beigesetzt. Sein Sohn Ahasja folgte ihm auf dem Thron.", footnotes: ["Die Davidsstadt umfasste das Gebiet des alten Jebus, das von David erobert worden war. Es bildete den Kern Jerusalems."] },
      { number: 25, text: "Im zwölften Regierungsjahr des Königs Joram Ben-Ahab von Israel wurde Ahasja Ben-Joram König von Juda.", heading: "Ahasja von Juda" },
      { number: 26, text: "Er war bei Herrschaftsantritt 22 Jahre alt und regierte nur ein Jahr in Jerusalem. Seine Mutter Atalja war eine Enkelin des Königs Omri von Israel." },
      { number: 27, text: "Er folgte dem bösen Beispiel der Sippe Ahabs, denn er war ja auch mit ihnen verschwägert. Er tat, was Jahwe verabscheute." },
      { number: 28, text: "Gemeinsam mit Joram Ben-Ahab zog er in den Kampf gegen König Hasaël von Syrien. Aber bei der Schlacht um Ramot* in Gilead* verwundeten die Syrer Joram.", footnotes: ["Ramot war als Levitenstadt dem Stamm Gad zugeteilt worden, befand sich jetzt aber in der Hand der Syrer. Die Stadt lag 58 km nördlich von Amman in Jordanien.", "Gilead war die Landschaft östlich des Jordan, Wohnsitz der Stämme Ruben, Gad und halb Manasse."] },
      { number: 29, text: "Deshalb zog sich der König nach Jesreel* zurück, um seine Wunden dort ausheilen zu lassen. Und dort besuchte ihn König Ahasja von Juda.", footnotes: ["Jesreel. Stadt zwischen Bet-Schean und Megiddo in der Jesreel-Ebene."] },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Der Prophet Elischa rief einen der Prophetenjünger zu sich und sagte zu ihm: \"Mach dich reisefertig, nimm diese Flasche mit Salböl und geh nach Ramot in Gilead.", heading: "Ein Gerichtsbringer in Israel (9-10)\nJehus Aufstand" },
      { number: 2, text: "Sieh dich dort nach Jehu Ben-Joschafat um, dem Enkel von Nimschi. Bitte ihn aus dem Kreis seiner Offiziere heraus und führe ihn in einen Raum, wo ihr allein seid." },
      { number: 3, text: "Dort gieße ihm das Salböl über den Kopf und sage: 'So spricht Jahwe: Hiermit habe ich dich zum König über Israel gesalbt!' Dann mach die Tür auf und lauf weg, so schnell du kannst!\"" },
      { number: 4, text: "Der Prophetenjünger, der ein Diener Elischas war, ging nach Ramot in Gilead." },
      { number: 5, text: "Als er ankam, saßen die Truppenführer beisammen. Er sagte: \"Ich habe eine Botschaft an dich, Oberst!\" Jehu fragte: \"An wen von uns?\" – \"An dich, Oberst!\", erwiderte er." },
      { number: 6, text: "Da stand Jehu auf und ging ins Haus. Dort goss der Prophetenjünger das Salböl über seinen Kopf und sagte: \"So spricht Jahwe: Hiermit habe ich dich zum König über Israel, das Volk Jahwes, gesalbt!" },
      { number: 7, text: "Du sollst die ganze Familie deines Herrn Ahab umbringen, denn so will ich das Blut meiner Propheten an Isebel rächen und das Blut aller Diener Jahwes." },
      { number: 8, text: "Ja, das ganze Haus Ahabs soll umkommen! Jeden Wandpisser* aus seiner Familie werde ich auslöschen, egal ob er gebunden oder frei* ist.", footnotes: ["Wandpisser. Das ist ein bewusst verächtlicher Ausdruck für einen erwachsenen Mann.", "gebunden oder frei. Wörtlich: \"den Festgehaltenen und Losgelassenen in Israel\". Das war offenbar ein Pauschalausdruck für alle Arten und Klassen von Menschen. Speziell könnte es Unmündige und Mündige meinen oder Sklaven und Freie."] },
      { number: 9, text: "Der Familie Ahabs wird es so ergehen wie den Familien von Jerobeam Ben-Nebat und Bascha Ben-Ahija*.", footnotes: ["... Ben-Ahija. Frühere Könige Israels, siehe 1. Könige 14,7-11; 16,1-12."] },
      { number: 10, text: "Isebels Leiche werden die Hunde im Stadtgebiet von Jesreel fressen, niemand wird sie begraben.\" Dann öffnete er die Tür und rannte weg." },
      { number: 11, text: "Als Jehu zu den anderen Offizieren seines Königs herauskam, fragten sie ihn: \"Ist alles in Ordnung? Warum ist dieser Verrückte zu dir gekommen?\" – \"Ihr wisst doch, was das für einer ist!\", entgegnete er. \"Gebt nichts auf sein Geschwätz!\"" },
      { number: 12, text: "Doch sie riefen: \"Ausflüchte! Heraus mit der Sprache!\" Da erwiderte Jehu: \"Er hat zu mir gesagt: 'So spricht Jahwe: Ich habe dich zum König über Israel gesalbt!'\"" },
      { number: 13, text: "Sofort nahmen sie ihre Mäntel und breiteten sie als Teppich auf der Treppe vor ihm aus. Sie bliesen das Signalhorn* und riefen: \"Jehu ist König!\"", footnotes: ["Das Signalhorn (Hebräisch: Schofar) war aus den gewundenen Hörnern des männlichen Fettschwanzschafes hergestellt und brachte einen dumpfen, durchdringenden Ton hervor."] },
      { number: 14, text: "So zettelte Jehu Ben-Joschafat, der Enkel Nimschis, eine Verschwörung zum Sturz Jorams an. – König Joram hatte mit ganz Israel Ramot in Gilead gegen König Hasaël von Syrien bewacht.", heading: "Jehu tötet Joram und Ahasja" },
      { number: 15, text: "In diesem Kampf war Joram aber verwundet worden und hatte sich nach Jesreel zurückgezogen, um dort seine Wunden ausheilen zu lassen. – Jehu sagte: \"Wenn ihr einverstanden seid, lassen wir niemand aus der Stadt entkommen, der etwas in Jesreel berichten kann.\"" },
      { number: 16, text: "Jehu jagte mit ein paar Streitwagen nach Jesreel, wo sich der kranke Joram befand. Auch König Ahasja von Juda war gerade dort, um ihn zu besuchen." },
      { number: 17, text: "Der Wächter auf dem Turm von Jesreel sah die Streitwagen Jehus herankommen. \"Eine Truppe mit Streitwagen kommt!\", meldete er dem König. \"Schick ihnen einen Reiter entgegen!\", befahl ihm Joram. \"Er soll fragen, ob sie in friedlicher Absicht kommen.\"" },
      { number: 18, text: "Der Reiter kam zu der Truppe und sagte dem Anführer: \"Der König lässt fragen, ob dein Kommen Frieden bedeutet.\" – \"Was geht dich der Frieden an?\", erwiderte Jehu. \"Reih dich hinter mir ein!\" Der Wächter berichtete: \"Der Bote ist zu ihnen gekommen, kehrt aber nicht zurück.\"" },
      { number: 19, text: "Da schickte der König einen zweiten Reiter los. Der kam hin und sagte: \"Der König lässt fragen, ob dein Kommen Frieden bedeutet.\" – \"Was geht dich der Frieden an?\", erwiderte Jehu. \"Reih dich hinter mir ein!\"" },
      { number: 20, text: "Der Wächter berichtete: \"Er ist zu ihnen gekommen, kehrt aber nicht zurück. Der Anführer von ihnen fährt wie ein Verrückter. Das kann nur Jehu sein!\"" },
      { number: 21, text: "Da befahl Joram: \"Spannt meinen Wagen an!\" Auch der Wagen des Königs Ahasja von Juda wurde angespannt. So zogen beide Könige Jehu entgegen. Auf dem Grundstück Nabots* von Jesreel trafen sie mit ihm zusammen.", footnotes: ["Grundstück Nabots. Siehe 1. Könige 21,1-16"] },
      { number: 22, text: "Als Joram Jehu erkannte, rief er: \"Ist Frieden, Jehu?\" Doch der schrie zurück: \"Wie kann Frieden sein, solange deine Mutter mit Götzen herumhurt und sich nur mit Zaubereien abgibt?\"" },
      { number: 23, text: "Da wendete Joram seinen Wagen und schrie: \"Verrat, Ahasja!\" und floh." },
      { number: 24, text: "Aber Jehu spannte seinen Bogen und traf Joram zwischen die Schulterblätter, sodass der Pfeil das Herz durchbohrte. Joram brach tot in seinem Wagen zusammen." },
      { number: 25, text: "Jehu befahl seinem Adjutanten Bidkar, dem dritten Mann im Wagen: \"Wirf ihn auf das Grundstück Nabots! Erinnerst du dich noch daran, wie wir zweispännig hinter seinem Vater herfuhren und Jahwe diese Drohung über ihn aussprach:" },
      { number: 26, text: "'Ich habe gesehen, wie man Nabot und seine Söhne gestern ermordet hat', spricht Jahwe. 'Hier, auf diesem Grundstück werde ich es dir vergelten*!', spricht Jahwe. Lade ihn also jetzt auf und wirf ihn auf das Grundstück, wie Jahwe es gesagt hat.\"", footnotes: ["vergelten. Siehe 1. Könige 21,19"] },
      { number: 27, text: "Als König Ahasja von Juda sah, was passierte, floh er in Richtung Bet-Gan*. Jehu jagte ihm nach und befahl seinen Leuten: \"Schießt auch ihn nieder!\" Sie verwundeten ihn auf seinem Wagen am Aufstieg von Gur in der Nähe von Jibleam*. Er kam noch bis Megiddo*; dort starb er.", footnotes: ["Bet-Gan lag 18 km südöstlich von Megiddo, am Südrand der Ebene Jesreel.", "Jibleam. Stadt 19 km südöstlich von Megiddo.", "Megiddo, bedeutende Stadt am südwestlichen Rand der Jesreel-Ebene. Die Festungsanlage überwachte einen wichtigen Pass durch die Bergkette des Karmel."] },
      { number: 28, text: "Seine Männer brachten ihn im Wagen nach Jerusalem und bestatteten ihn in der Davidsstadt, in der Grabstätte der Königsfamilie." },
      { number: 29, text: "Ahasja war im 11. Regierungsjahr von Joram Ben-Ahab König über Juda geworden." },
      { number: 30, text: "Jehu kehrte nach Jesreel zurück. Sobald Isebel davon gehört hatte, schminkte sie ihre Augenlider, schmückte den Kopf und lehnte sich aus dem Fenster.", heading: "Isebels Ende" },
      { number: 31, text: "Als Jehu dann durchs Tor fuhr, sagte sie: \"Na, hast du nun Frieden, du Simri*, Mörder deines Herrn?\"", footnotes: ["du Simri. Siehe 1. Könige 16,9-15."] },
      { number: 32, text: "Er blickte zum Fenster hoch und rief: \"Wer hält zu mir, wer?\" Ein paar Hofbeamte schauten zu ihm hinunter." },
      { number: 33, text: "Da rief er: \"Werft sie runter!\" Sie taten es. Dabei spritzte ihr Blut an die Wand und an die Pferde, von denen Jehu sie zertreten ließ." },
      { number: 34, text: "Danach ging er in den Palast und ließ sich Essen und Trinken vorsetzen. Nach dem Mahl sagte er: \"Seht doch nach dieser Verfluchten und begrabt sie! Sie ist immerhin eine Königstochter.\"" },
      { number: 35, text: "Aber die Diener, die sie begraben wollten, fanden nur noch ihren Schädel, die Füße und die Hände." },
      { number: 36, text: "Sie berichteten es Jehu. Da sagte er: \"So hat sich erfüllt, was Jahwe durch seinen Diener Elija von Tischbe sagen ließ: 'Auf dem Boden von Jesreel sollen die Hunde das Fleisch Isebels fressen," },
      { number: 37, text: "und ihre Leiche soll wie Mist auf dem Acker werden, dass niemand mehr sagen kann: Das ist Isebel!'\"*", footnotes: ["Das ist Isebel. Siehe 1. Könige 21,23!"] },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Jehu schickte Briefe nach Samaria, wo siebzig Söhne und Enkel von Ahab lebten. Er schrieb an die Bevollmächtigten von Jesreel, an die Ältesten der Stadt und die Erzieher der Söhne Ahabs:", heading: "Untergang der Familie Ahabs" },
      { number: 2, text: "\"Bei euch sind die Söhne eures Herrn, ihr verfügt über Streitwagen und Pferde, habt Waffen und eine gut befestigte Stadt. Wenn dieser Brief euch erreicht," },
      { number: 3, text: "dann wählt den fähigsten unter den Söhnen eures Herrn aus, setzt ihn auf den Thron seines Vaters und kämpft für das Königtum eures Herrn!\"" },
      { number: 4, text: "Aber sie bekamen große Angst und sagten sich: \"Seht doch, mit den beiden Königen ist er schon fertig geworden, wie wollen wir denn da bestehen?\"" },
      { number: 5, text: "Da ließen der Palastvorsteher, der Stadtkommandant, die Ältesten und die Erzieher Jehu ausrichten: \"Wir stehen dir zu Diensten und werden alles tun, was du von uns verlangst. Wir wollen hier niemand zum König machen. Tu, was du für richtig hältst!\"" },
      { number: 6, text: "Da schrieb Jehu einen zweiten Brief, in dem es hieß: \"Wenn ihr auf meiner Seite steht und bereit seid, mir zu gehorchen, dann kommt morgen um diese Zeit zu mir nach Jesreel und bringt die Köpfe der Söhne eures Herrn mit.\" Die siebzig Prinzen wurden nämlich von den Großen der Stadt aufgezogen." },
      { number: 7, text: "Als der Brief sie erreichte, ließen sie die siebzig Nachkommen des Königs enthaupten, packten ihre Köpfe in Körbe und ließen sie nach Jesreel bringen." },
      { number: 8, text: "Als Jehu gemeldet wurde, dass man die Köpfe der Prinzen gebracht hatte, befahl er: \"Stapelt sie in zwei Haufen vor dem Stadttor auf und lasst sie bis morgen früh dort liegen!\"" },
      { number: 9, text: "Am nächsten Morgen trat er vor das Tor und sagte zu dem dort versammelten Volk: \"Ihr seid ohne Schuld! Ich habe mich ja gegen meinen Herrn verschworen und ihn umgebracht. Aber wer hat die hier alle umgebracht?" },
      { number: 10, text: "Daran könnt ihr erkennen, dass alles eintrifft, was Jahwe der Familie Ahabs angedroht hat. Jahwe hat getan, was er durch seinen Diener Elija angekündigt hatte.\"" },
      { number: 11, text: "Danach ließ Jehu auch in Jesreel die Angehörigen von Ahab umbringen, ebenso seine hohen Beamten, seine Vertrauten und seine Priester. Keiner kam mit dem Leben davon." },
      { number: 12, text: "Dann machte er sich auf den Weg nach Samaria. Bei Bet-Eked-Roïm" },
      { number: 13, text: "traf er auf Verwandte des Königs Ahasja von Juda. \"Wer seid ihr?\", fragte er. \"Wir sind Verwandte Ahasjas und wollen die Söhne des Königs und auch die der Königsmutter besuchen\", antworteten sie." },
      { number: 14, text: "\"Packt sie lebendig!\", befahl Jehu. Seine Männer nahmen alle gefangen und erschlugen sie bei der Zisterne von Bet-Eked. Es waren 42 Mann, keiner kam mit dem Leben davon." },
      { number: 15, text: "Als Jehu seinen Weg fortsetzte, traf er auf Jonadab von der Sippe Rechab*. Er grüßte ihn und fragte: \"Du denkst doch so wie ich. Kann ich dir trauen?\" – \"Ja\", erwiderte Jonadab. \"Dann gib mir deine Hand!\", sagte Jehu. Jonadab reichte ihm die Hand. Dann ließ Jehu ihn zu sich auf den Wagen steigen", footnotes: ["Die Angehörigen der Sippe Rechab waren extrem konservativ und lehnten den Baalskult ab. Sie lebten wie Nomaden in Israel und weigerten sich, in Häusern zu wohnen, Felder zu bebauen und Wein zu trinken. Jonadab war das damalige Oberhaupt dieser Sippe, siehe Jeremia 35."] },
      { number: 16, text: "und sagte: \"Komm mit mir und sieh dir mein leidenschaftliches Eintreten für Jahwe an!\" Jonadab fuhr mit." },
      { number: 17, text: "Als Jehu in Samaria ankam, brachte er alle um, die dort von Ahabs Verwandtschaft noch übrig geblieben waren. Die ganze Familie Ahabs wurde ausgelöscht, wie es Jahwe schon zu Elija gesagt hatte." },
      { number: 18, text: "Nun versammelte Jehu das ganze Volk von Samaria und kündigte ihm an: \"Ahab hat Baal nur wenig gedient, Jehu wird ihm viel mehr Verehrung zukommen lassen.", heading: "Beseitigung der Baalspriester" },
      { number: 19, text: "Ruft alle Propheten Baals zu mir! Alle seine Diener und alle seine Priester sollen kommen! Niemand darf fehlen! Ich will nämlich ein großes Opferfest für Baal veranstalten. Wer vermisst wird, muss mit dem Tod rechnen.\" Das war nur eine List, denn Jehu wollte alle Diener Baals umbringen." },
      { number: 20, text: "Er befahl, eine Festversammlung zu Ehren des Baal auszurufen," },
      { number: 21, text: "und schickte Boten in ganz Israel umher. Da kamen alle Baalsdiener in Samaria zusammen. Sie versammelten sich im Tempel des Baal, der sich von einem Ende bis zum anderen mit Menschen füllte." },
      { number: 22, text: "Dann befahl er dem Verwalter der Kleiderkammer: \"Gib für alle Diener Baals Festgewänder aus!\" Nachdem das geschehen war," },
      { number: 23, text: "ging er zusammen mit Jonadab, dem Nachkommen Rechabs, in den Götzentempel und rief den Anhängern Baals zu: \"Seht euch gründlich um und sorgt dafür, dass kein Diener Jahwes hier ist! Nur Leute, die den Baal verehren, dürfen anwesend sein!\"" },
      { number: 24, text: "Dann traten beide an den Altar, um Schlacht- und Brandopfer für Baal darzubringen. Draußen hatte Jehu 80 Mann aufgestellt und ihnen gesagt: \"Wer von euch einen der Baalsdiener entkommen lässt, bezahlt das mit seinem Leben!\"" },
      { number: 25, text: "Als man mit der Zubereitung der Opfer fertig war, befahl Jehu seiner Leibwache und den Offizieren: \"Kommt herein und erschlagt sie alle! Keiner darf entkommen!\" Da brachten sie alle Baalsdiener um und warfen ihre Leichen hinaus. Dann gingen sie in den innersten Bereich des Tempels," },
      { number: 26, text: "holten die geweihten Steinbilder heraus und warfen sie ins Feuer." },
      { number: 27, text: "Auch die Steinsäule, die zu Ehren des Baal aufgestellt worden war, stürzten sie um und rissen den ganzen Tempel nieder. Bis heute wird der Platz als öffentlicher Abort genutzt." },
      { number: 28, text: "So beseitigte Jehu den Baal aus Israel." },
      { number: 29, text: "Doch von dem sündhaften Gottesdienst vor den goldenen Stierbildern* in Bet-El und Dan, zu dem Jerobeam Ben-Nebat Israel verführt hatte, wollte er nicht lassen.", footnotes: ["Diese Stierbilder sollten wie das goldene Kalb auf der Wüstenwanderung Symbole für Jahwe sein, die jedoch einen Abfall von ihm gleichkamen. Jerobeam hatte eins davon im Süden seines Reiches (Bet-El) und eins im Norden (Dan) aufgestellt."] },
      { number: 30, text: "Jahwe sagte zu Jehu: \"Weil du bereit warst, das Rechte vor mir zu tun und an Ahabs Familie zu vollstrecken, was ich ihr zugedacht hatte, sollen deine Nachkommen bis in die vierte Generation Könige Israels sein.\"" },
      { number: 31, text: "Aber Jehu achtete nicht darauf, das Gesetz Jahwes, des Gottes Israels, mit ganzem Herzen zu befolgen. Er ließ nicht von dem sündhaften Gottesdienst ab, zu dem Jerobeam Israel verführt hatte." },
      { number: 32, text: "In dieser Zeit begann Jahwe Israel zu verstümmeln. Hasaël durfte sie in dem Gebiet Israels schlagen," },
      { number: 33, text: "das östlich vom Jordan liegt, von der Stadt Aroer am Arnon an, das Land Gilead hinauf bis nach der Landschaft Baschan, was dem ganzen Stammesgebiet von Gad, Ruben und Ost-Manasse entsprach." },
      { number: 34, text: "Was sonst noch über Jehus Herrschaft zu sagen ist, über seine Taten und Erfolge, findet man in der Chronik der Könige von Israel." },
      { number: 35, text: "Jehu starb und wurde in Samaria bestattet. Sein Sohn Joahas trat die Herrschaft an." },
      { number: 36, text: "28 Jahre lang hatte Jehu in Samaria über Israel regiert." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Als Atalja, die Mutter von Ahasja, erfuhr, dass ihr Sohn tot war, ließ sie die ganze königliche Nachkommenschaft umbringen.", heading: "Ein Gerichtsbote in Juda (11-12)\nAtalja und Joasch" },
      { number: 2, text: "Doch Joscheba*, die Tochter von König Joram und Schwester Ahasjas, hatte dessen kleinen Sohn Joasch aus der Mitte der Prinzen, die getötet werden sollten, heimlich beiseite geschafft. Sie hatte ihn und seine Amme in der Bettenkammer versteckt und so vor Atalja in Sicherheit gebracht.", footnotes: ["Nach 2. Chronik 22,11war Joscheba die Frau des Hohen Priesters Jojada."] },
      { number: 3, text: "Sechs Jahre lang hielt sie ihn dann im Bereich des Tempels verborgen, während Atalja das Land regierte." },
      { number: 4, text: "Im siebten Jahr ließ der Priester Jojada die Offiziere der königlichen Leibgarde* und der Palastwache zu sich in den Tempel Jahwes kommen. Dort schloss er ein Bündnis mit ihnen. Er ließ sie Treue schwören und zeigte ihnen den Sohn des Königs.", footnotes: ["Wörtlich:Karer. Die Leibgarde bestand in diesem Fall aus karischen Söldnern, die aus dem Südwesten Kleinasiens stammten."] },
      { number: 5, text: "Dann gab er ihnen folgende Weisung: \"Ein Drittel von euren Leuten, die am Sabbat den Dienst antreten, soll den Palast des Königs bewachen," },
      { number: 6, text: "ein weiteres Drittel soll am Tor Sur Wache halten und das letzte Drittel am Tor hinter dem Haus der Palastwache. So sollt ihr abwechselnd die Bewachung des Tempels übernehmen." },
      { number: 7, text: "Die zwei Abteilungen von euch, die ihren Dienst am Sabbat gerade beenden, sollen im Tempel bleiben und den König beschützen." },
      { number: 8, text: "Ihr sollt mit der Waffe in der Hand den König umgeben und jeden töten, der in den Kreis einzudringen versucht. Auf Schritt und Tritt müsst ihr den König begleiten.\"" },
      { number: 9, text: "Die Offiziere befolgten genau die Anweisungen des Priesters. Jeder nahm seine Männer zusammen und zwar die, die am Sabbat ihren Dienst antraten, und die, die ihn beendeten. So kamen sie zu Jojada." },
      { number: 10, text: "Der Priester übergab den Offizieren die Speere und Schilde, die noch von König David stammten und im Tempel Jahwes aufbewahrt wurden." },
      { number: 11, text: "Daraufhin stellten sich die Leibwächter auf, jeder mit den Waffen in der Hand, von der rechten Seite des Tempelhofes am Altar und dem Tempelhaus vorbei bis zur linken Seite, um den König nach allen Seiten abzusichern." },
      { number: 12, text: "Dann führte Jojada den Prinzen heraus. Er setzte ihm die Krone auf und überreichte ihm die Urkunde. Dann wurde er gesalbt und so zum König gemacht. Alle klatschten in die Hände und riefen: \"Es lebe der König!\"" },
      { number: 13, text: "Als Atalja die Jubelrufe der Palastwache und des Volkes hörte, kam auch sie zum Haus Jahwes." },
      { number: 14, text: "Da sah sie den König nach dem Brauch auf der obersten Stufe des Tempeleingangs stehen, umgeben von den Offizieren und Trompetern. Das Volk jubelte vor Freude, und die Trompeten schmetterten. Da riss Atalja ihr Obergewand ein und schrie: \"Verrat! Verschwörung!\"" },
      { number: 15, text: "Doch Jojada befahl den Offizieren, die das Kommando über die Truppen hatten: \"Führt sie durch die Reihen eurer Leute hinaus. Wer ihr folgt, den tötet mit dem Schwert!\" Er wollte nämlich nicht, dass man sie im Tempelhof umbrachte." },
      { number: 16, text: "Da packten sie Atalja und brachten sie auf dem Reiterweg in den Palastbezirk. Dort wurde sie getötet." },
      { number: 17, text: "Inzwischen ließ Jojada den König und das Volk in den Bund mit Jahwe eintreten. Sie verpflichteten sich, das Volk Jahwes zu sein. Auch zwischen König und Volk wurde ein Bund geschlossen." },
      { number: 18, text: "Dann zog das ganze Volk zum Baalstempel und riss ihn nieder. Sie zertrümmerten seine Altäre und Götzenbilder und erschlugen den Baalspriester Mattan dort vor den Altären.Nachdem der Priester Wachen zum Schutz des Tempels Jahwes aufgestellt hatte," },
      { number: 19, text: "rief er die Offiziere, die Leibgarde, die Palastwache und das ganze Volk zusammen. Dann geleiteten sie den König durch das Tor der Palastwache in den Königspalast. Dort nahm er auf dem Königsthron Platz." },
      { number: 20, text: "Das ganze Volk freute sich und die Stadt blieb ruhig, obwohl Atalja im Palastbezirk mit dem Schwert getötet worden war." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Joasch war bei Regierungsantritt sieben Jahre alt.", heading: "Joasch von Juda" },
      { number: 2, text: "Er wurde im siebten Regierungsjahr des Königs Jehu von Israel König und regierte 40 Jahre* in Jerusalem. Seine Mutter hieß Zibja und stammte aus Beerscheba.", footnotes: ["40 Jahre. 835-796 v.Chr."] },
      { number: 3, text: "Joasch tat sein ganzes Leben lang, was Jahwe gefiel, weil der Priester Jojada ihn unterwiesen hatte." },
      { number: 4, text: "Die Opferstätten auf den Höhen ließ er allerdings bestehen, sodass das Volk dort auch weiterhin Schlacht- und Räucheropfer brachte." },
      { number: 5, text: "Eines Tages erklärte Joasch den Priestern: \"Alles Geld, das als Weihegabe in den Tempel Jahwes gebracht wird – das Geld, das bei der Musterung zu zahlen ist,* das Geld, das jemand bei der Einlösung von Gelübden zahlt*, und das Geld, das jemand freiwillig dem Haus Jahwes zukommen lässt –,", footnotes: ["zu zahlen ist. Siehe 2. Mose 30,11-16", "Gelübden zahlt. Siehe 3. Mose 27,2-8"] },
      { number: 6, text: "sollen die Priester in Empfang nehmen, und zwar jeder von seinem Geldeinnehmer*. Davon sollen sie die Reparaturen am Tempel ausführen lassen.\"", footnotes: ["Diese Geldeinnehmer (wörtlich: Kaufleute) gingen den Priestern bei den finanziellen Angelegenheiten des Tempels zur Hand, z.B. bei der Festsetzung von Kosten oder dem Wert eines Opfertiers."] },
      { number: 7, text: "Aber im 23. Regierungsjahr von König Joasch* hatten die Priester immer noch nichts am Tempel ausgebessert.", footnotes: ["23 ... Joasch. Der König hatte diesen Plan zur Renovierung des Tempels einige Jahre vorher in Kraft gesetzt, aber er funktionierte nicht. Jetzt, im Alter von 30 Jahren, ordnete er die Sache neu."] },
      { number: 8, text: "Da rief der König Jojada und die anderen Priester zu sich und fragte: \"Warum habt ihr den Tempel immer noch nicht ausbessern lassen? Ab sofort sollt ihr von den Geldeinnehmern kein Geld mehr in Empfang nehmen, denn dieses Geld ist ganz für die Instandsetzung des Tempels bestimmt.\"" },
      { number: 9, text: "Die Priester waren einverstanden, kein Geld mehr vom Volk anzunehmen, dann aber auch nicht mehr für die Instandsetzung des Tempels verantwortlich zu sein." },
      { number: 10, text: "Der Priester Jojada ließ nun einen Kasten anfertigen, in dessen Deckel man ein Loch gebohrt hatte, und stellte ihn neben den Altar rechts vom Tempeleingang auf. In diesen Kasten legten die Priester, die den Eingang bewachten, alles Geld, das in den Tempel gebracht wurde." },
      { number: 11, text: "Wenn der Kasten voll war, ließen sie den Staatsschreiber und den Hohen Priester kommen. Unter deren Aufsicht wurde das Silber in Beutel gepackt und gewogen." },
      { number: 12, text: "Danach wurde es den Meistern ausgehändigt, die für die Bauarbeiten am Tempel verantwortlich waren. Diese bezahlten damit die Handwerker, die am Tempel Jahwes arbeiteten, die Zimmerleute," },
      { number: 13, text: "die Maurer und die Steinhauer. Und diese wiederum kauften davon das Bauholz, die Steine und was sonst noch für die Ausbesserung des Tempels gebraucht wurde." },
      { number: 14, text: "Man ließ von diesem Geld aber keine Silberschüsseln, Messer, Sprengschalen, Trompeten oder andere Gegenstände aus Gold oder Silber anfertigen," },
      { number: 15, text: "sondern gab alles den Meistern für die Ausbesserungsarbeiten am Tempel Jahwes." },
      { number: 16, text: "Von diesen Männern wurde keine Rechenschaft über die Ausgaben verlangt. Sie handelten auf Treu und Glauben." },
      { number: 17, text: "Doch das Geld, das von den Schuld- und Sündopfern einkam, wurde nicht für die Instandsetzung des Tempels verwendet. Es war für die Priester." },
      { number: 18, text: "Damals* griff König Hasaël von Syrien die Philisterstadt Gat an* und eroberte sie. Danach wollte er auch Jerusalem angreifen.", footnotes: ["Damals. Das muss gegen Ende der Regierungszeit Joaschs gewesen sein, jedenfalls nach dem Tod des Priesters Jojada, siehe 2. Chronik 24,17-24.", "Um Gat anzugreifen musste er mit seiner Armee quer durch Judäa ziehen."] },
      { number: 19, text: "Doch der König von Juda nahm alle Weihgaben, die seine Vorgänger Joschafat, Joram und Ahasja für das Heiligtum gestiftet hatten, seine eigenen Weihgaben und alles Gold, das sich in den Schatzkammern des Tempels und seines Palastes befand, und ließ es dem König von Syrien überbringen. Da zog Hasaël seine Truppen von Jerusalem ab." },
      { number: 20, text: "Was sonst noch über Joaschs Herrschaft zu sagen ist, findet man in der Chronik der Könige von Juda." },
      { number: 21, text: "Er fiel einer Verschwörung seiner Hofleute zum Opfer und wurde in einem Haus des Stadtwalls ermordet und zwar dort, wo der Weg nach Silla* hinabführt.", footnotes: ["Die Bezeichnung Silla ist unbekannt. Es muss ein bestimmter Weg ins Kidrontal hinab gewesen sein."] },
      { number: 22, text: "Die Tat wurde von Josachar Ben-Schimat und Josabat Ben-Schomer begangen. Joasch wurde in der Grabstätte seiner Vorfahren in der Davidsstadt beigesetzt und sein Sohn Amazja trat die Herrschaft an." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Im 23. Regierungsjahr von Joasch Ben-Ahasja, dem König von Juda, wurde Joahas Ben-Jehu König von Israel und regierte 17 Jahre* in Samaria.", heading: "Der Weg in die assyrische Gefangenschaft (13-17)\nJoahas von Israel", footnotes: ["17 Jahre. 814-796 v.Chr."] },
      { number: 2, text: "Was er tat, war böse vor Jahwe. Er hörte nicht mit dem sündhaften Gottesdienst auf, zu dem Jerobeam Ben-Nebat Israel verführt hatte." },
      { number: 3, text: "Das erregte den Zorn Jahwes gegen Israel, und er gab sie immer wieder in die Gewalt des Syrerkönigs Hasaël und seines Sohnes Ben-Hadad." },
      { number: 4, text: "Als Joahas jedoch Jahwe um Hilfe anrief, hörte Jahwe auf ihn, denn er sah, wie sehr die Israeliten vom Syrerkönig unterdrückt wurden." },
      { number: 5, text: "Da schickte er ihnen einen Retter, so dass sie sich aus der Gewalt der Syrer befreien und wie vorher in Frieden leben konnten." },
      { number: 6, text: "Dennoch hörten sie nicht mit dem sündhaften Gottesdienst auf, zu dem Jerobeam Ben-Nebat Israel verführt hatte. Sie wollten einfach nicht davon lassen. Und auch das Pfahlbild der Aschera* blieb in Samaria.", footnotes: ["Die Aschera war eine Fruchtbarkeitsgöttin, die in handlichen Figuren, geweihten Bäumen oder Pfählen verehrt wurde."] },
      { number: 7, text: "Jahwe hatte Joahas von seinem ganzen Heer nur noch 50 Gespannpferde übrig gelassen, 10 Streitwagen und 10.000 Mann zu Fuß. Alles andere hatte der Syrerkönig vernichtet. Er hatte sie wie Staub zertreten." },
      { number: 8, text: "Was sonst noch über die Herrschaft von Joahas zu sagen ist, über seine Taten und Erfolge, findet man in der Chronik der Könige von Israel." },
      { number: 9, text: "Als Joahas starb, wurde er in Samaria bestattet und sein Sohn Joasch trat die Herrschaft an." },
      { number: 10, text: "Im 37. Regierungsjahr des Königs Joasch von Juda wurde Joasch Ben-Joahas König über Israel und regierte 16 Jahre* in Samaria.", heading: "Joasch und der sterbende Elischa", footnotes: ["16 Jahre. 798-782 v.Chr."] },
      { number: 11, text: "Er tat, was Jahwe verabscheute, und machte mit dem sündhaften Gottesdienst weiter, zu dem Jerobeam Ben-Nebat Israel verführt hatte." },
      { number: 12, text: "Was sonst noch über die Herrschaft von Joasch zu sagen ist, über seine Taten und Erfolge, auch über den Krieg gegen Amazja von Juda, findet man in der Chronik der Könige von Israel." },
      { number: 13, text: "Als Joasch starb, kam Jerobeam auf den Thron. Joasch wurde in der Grabstätte der Könige von Israel in Samaria bestattet." },
      { number: 14, text: "Zu der Zeit, als Elischa schwer krank wurde und im Sterben lag, war König Joasch von Israel zu ihm gekommen. Weinend beugte er sich über ihn und sagte: \"Mein Vater, mein Vater! Du Streitwagen Israels, du, sein Gespann!\"" },
      { number: 15, text: "Da sagte Elischa zu ihm: \"Hol einen Bogen und Pfeile!\" Der König tat es." },
      { number: 16, text: "Dann sagte er: \"Spann den Bogen!\" Joasch tat es. Nun legte Elischa seine Hände auf die Hände des Königs." },
      { number: 17, text: "Dann sagte er: \"Öffne das Fenster, das nach Osten geht!\" Nachdem der König das getan hatte, sagte Elischa: \"Schieß!\" Der König schoss den Pfeil ab und Elischa sagte: \"Dieser Pfeil ist ein Zeichen für die Rettung, die von Jahwe kommt, ein Pfeil der Rettung durch den Sieg über die Syrer. Bei Afek* wirst du sie vernichtend schlagen!\"", footnotes: ["Afek lag vermutlich am Ostufer des Sees Gennesaret. 60 Jahre vorher hatte König Ahab dort einen entscheidenden Sieg über die Syrer unter Ben-Hadad II. errungen, siehe 1. Könige 20,26-30."] },
      { number: 18, text: "Dann befahl ihm Elischa: \"Nimm jetzt die übrigen Pfeile in die Hand!\" Joasch nahm sie und Elischa sagte: \"Schlag damit auf den Boden!\" Er schlug dreimal und hielt dann inne." },
      { number: 19, text: "Da wurde der Gottesmann zornig über ihn und sagte: \"Fünf oder sechsmal hättest du schlagen sollen, dann hättest du die Syrer vernichtet! Jetzt wirst du sie nur dreimal besiegen.\"" },
      { number: 20, text: "Elischa starb und wurde in einer Grabhöhle bestattet.*Als es Frühling wurde, machten moabitische Räuberbanden das Land unsicher.", footnotes: ["Grabhöhle bestattet. Wörtlich:begraben. Elischa wurde vermutlich wie die meisten Israeliten der Frühzeit in Leinen eingewickelt und in einem aus Felsen gehauenen Grab oder einer Höhle (V. 21) bestattet."] },
      { number: 21, text: "Einmal wollte man gerade einen Mann bestatten, als solch eine Räuberbande auftauchte. Da warfen die Leute den Leichnam einfach in die Grabhöhle Elischas. Als der Tote mit den Gebeinen Elischas in Berührung kam, wurde er wieder lebendig und stand auf." },
      { number: 22, text: "So lange Joahas regierte, bedrängte König Hasaël von Syrien Israel." },
      { number: 23, text: "Aber Jahwe schenkte den Israeliten wieder seine Gnade. Er erbarmte sich über sie und half ihnen wegen seines Bundes mit Abraham, Isaak und Jakob. Er wollte sie nicht zugrunde gehen lassen und hatte sie bis jetzt auch noch nicht aus seiner Gegenwart verbannt." },
      { number: 24, text: "Als daher König Hasaël von Syrien starb und sein Sohn Ben-Hadad die Herrschaft antrat," },
      { number: 25, text: "konnte Joasch Ben-Joahas Ben-Hadad die Städte wieder entreißen, die sein Vater Joahas an dessen Vater verloren hatte. Dreimal besiegte Joasch ihn und eroberte die Städte zurück." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Im zweiten Regierungsjahr von König Joasch Ben-Joahas von Israel wurde Amazja Ben-Joasch König von Juda.", heading: "Amazja von Juda" },
      { number: 2, text: "Er war bei Herrschaftsantritt 25 Jahre alt und regierte 29 Jahre lang in Jerusalem.* Seine Mutter stammte aus Jerusalem und hieß Joaddan.", footnotes: ["29 ... Jerusalem. 796-767 v.Chr. In den 29 Jahren ist die 24-jährige Mitregentschaft mit seinem Sohn Asarja eingeschlossen."] },
      { number: 3, text: "Er tat wie sein Vater Joasch, was Jahwe gut gefiel, nur nicht ganz so wie sein Vorfahr David." },
      { number: 4, text: "Die Opferstätten auf den Höhen ließ er nämlich bestehen, sodass das Volk auch weiterhin dort Schlacht- und Räucheropfer brachte." },
      { number: 5, text: "Als Amazja die Herrschaft fest in Händen hatte, ließ er die Hofbeamten töten, die seinen Vater Joasch ermordet hatten." },
      { number: 6, text: "Doch ihre Söhne ließ er am Leben, wie es das Gebot Jahwes besagt, das im Gesetzbuch des Mose steht: \"Die Väter sollen nicht für die Schuld ihrer Söhne sterben und die Söhne nicht für die Schuld ihrer Väter. Jeder soll nur für seine eigene Sünde bestraft werden.\"*", footnotes: ["... bestraft werden. 5. Mose 24,16"] },
      { number: 7, text: "Amazja schlug die Edomiter im Salztal*, die mit einem 10.000 Mann starken Heer gegen ihn angetreten waren. Er eroberte auch die Stadt Sela* und nannte sie Jokteel. So heißt sie bis heute.", footnotes: ["Salztal ist dasselbe Schlachtfeld, auf dem schon David die Edomiter schlug, siehe 2. Samuel 8,13, das 15 km breite Tal der Araba südlich des Toten Meeres.", "Sela heißt Felsen. Nach Richter 1,36lag die edomitische Festung 37 km südöstlich von der Spitze des Toten Meeres in der Araba und ist nicht identisch mit Petra."] },
      { number: 8, text: "Darauf schickte Amazja Boten zu König Joasch Ben-Joahas von Israel, dem Enkel Jehus, und ließ ihm ausrichten: \"Komm, wir wollen unsere Kräfte messen!\"" },
      { number: 9, text: "Doch König Joasch ließ ihm sagen: \"Der Dornstrauch auf dem Libanon sagte zur Zeder: 'Gib meinem Sohn deine Tochter zur Frau!' Aber die wilden Tiere auf dem Libanon liefen über den Dornstrauch und zertrampelten ihn." },
      { number: 10, text: "Ist dir der Sieg über die Edomiter zu Kopf gestiegen? Genieße deinen Ruhm und bleib zu Hause! Warum willst du dich ins Unglück stürzen und reißt ganz Juda mit hinein?\"" },
      { number: 11, text: "Doch Amazja wollte nicht hören. Da zog König Joasch von Israel mit einem Heer nach Juda. Bei Bet-Schemesch* kam es zur Schlacht zwischen ihm und König Amazja von Juda.", footnotes: ["Bet-Schemesch liegt 24 km westlich von Jerusalem in der Nähe der Grenze zwischen Juda und Dan, siehe Josua 15,10."] },
      { number: 12, text: "Die Männer Judas wurden von den Israeliten besiegt und flüchteten nach Hause." },
      { number: 13, text: "König Joasch von Israel nahm König Amazja Ben-Joasch von Juda, den Enkel Ahasjas, bei Bet-Schemesch gefangen. Anschließend rückte er nach Jerusalem vor und ließ die Stadtmauer auf einer Länge von 200 Metern zwischen dem Ephraïmtor und dem Ecktor niederreißen." },
      { number: 14, text: "Er räumte alles Gold und Silber und alle kostbaren Gegenstände aus dem Tempel und den Schatzkammern des Palastes aus und nahm dazu eine Anzahl von Geiseln nach Samaria mit." },
      { number: 15, text: "Was sonst noch über die Herrschaft von Joasch zu sagen ist, über seine Taten und Erfolge, auch über den Krieg gegen Amazja von Juda, findet man in der Chronik der Könige von Israel." },
      { number: 16, text: "Als Joasch starb, wurde er in der Grabstätte der Könige von Israel in Samaria bestattet und sein Sohn Jerobeam trat die Herrschaft an." },
      { number: 17, text: "König Amazja Ben-Joasch von Juda überlebte König Joasch Ben-Joahas von Israel um 15 Jahre." },
      { number: 18, text: "Was sonst noch über die Herrschaft Amazjas zu sagen ist, findet man in der Chronik der Könige von Juda." },
      { number: 19, text: "Als es in Jerusalem zu einer Verschwörung gegen ihn kam, floh er nach Lachisch. Aber die Verschwörer ließen ihn bis dorthin verfolgen und umbringen." },
      { number: 20, text: "Man brachte ihn auf Pferden nach Jerusalem und bestattete ihn in der Davidsstadt in der Grabstätte seiner Vorfahren." },
      { number: 21, text: "Das ganze Volk Judas hatte seinen Sohn Asarja schon mit 16 Jahren zum König gemacht*.", footnotes: ["zum König gemacht. Das geschah bereits 24 Jahre vor dem Tod Amazjas. Entweder war Asarja seitdem Mitregent oder sogar Gegenkönig."] },
      { number: 22, text: "Nach dem Tod seines Vaters eroberte Asarja die Stadt Elat* für Juda zurück und baute sie wieder auf.", footnotes: ["Elat liegt an der Nordspitze des Golfs von Akaba, etwa 175 km südlich von der Südspitze des Toten Meeres."] },
      { number: 23, text: "Im 15. Regierungsjahr* von König Amazja Ben-Joasch von Juda wurde Jerobeam Ben-Joasch König von Israel. Er regierte 41 Jahre in Samaria", heading: "Jerobeam II. von Israel", footnotes: ["15. Regierungsjahr. 782 v.Chr. In diesem Jahr begann Jerobeams Alleinherrschaft. Seine gesamte Regierungszeit dauerte von 793-753 v.Chr."] },
      { number: 24, text: "und tat, was Jahwe verabscheute. Er hörte nicht mit dem sündhaften Gottesdienst auf, zu dem Jerobeam Ben-Nebat Israel verführt hatte." },
      { number: 25, text: "Doch es gelang ihm, die Gebiete zurückzuerobern, die zu Israel gehörten, von Lebo-Hamat* bis hinunter zum Meer der Araba*. Damit erfüllte sich, was Jahwe, der Gott Israels, durch seinen Diener Jona Ben-Amittai* aus Gat-Hefer* angekündigt hatte.", footnotes: ["Lebo-Hamat. Heute: Labwe, etwa 70 km nördlich vom Hermon-Gebirge.", "Araba meint den bis zu 20 km breiten Jordangraben zwischen dem See Gennesaret und dem Toten Meer. Das Meer der Araba ist das Tote Meer.", "Jona Ben-Amittai. Siehe dazu das Buch des Propheten Jona.", "Das Dorf Gat-Hefer liegt 5 km nordöstlich vom heutigen Nazaret."] },
      { number: 26, text: "Denn Jahwe hatte das bittere Elend Israels gesehen, dass sie allesamt am Ende waren und dass niemand da war, der ihnen half." },
      { number: 27, text: "Jahwe hatte es nicht im Sinn, den Namen Israels in der Welt verschwinden zu lassen. Darum half er ihnen durch Jerobeam Ben-Joasch." },
      { number: 28, text: "Was sonst noch über die Herrschaft von Jerobeam zu sagen ist, über seine Taten und Erfolge, wie er Krieg geführt hat und Damaskus und Hamat* für Israel zurückgewann, findet man in der Chronik der Könige von Israel.", footnotes: ["Hamat. 72 km nördlich von Damaskus."] },
      { number: 29, text: "Als Jerobeam starb, wurde er in der Grabstätte der Könige von Israel bestattet und sein Sohn Secharja trat die Herrschaft an." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Im 27. Regierungsjahr des Königs Jerobeam von Israel wurde Asarja Ben-Amazja König von Juda.", heading: "Asarja (Usija) von Juda" },
      { number: 2, text: "Er war 16 Jahre alt gewesen, als er Mitregent wurde, und regierte insgesamt 52 Jahre lang in Jerusalem. Seine Mutter hieß Jecholja und stammte aus Jerusalem." },
      { number: 3, text: "Wie sein Vater Amazja tat auch er, was Jahwe gefiel." },
      { number: 4, text: "Die Opferstätten auf den Höhen ließ er allerdings bestehen, sodass das Volk dort auch weiterhin Schlacht- und Räucheropfer brachte." },
      { number: 5, text: "Jahwe schlug den König mit Aussatz. Er musste bis zu seinem Tod in einem abgesonderten Haus wohnen. Die Regierungsgeschäfte und die Aufsicht über den Palast übergab er seinem Sohn Jotam." },
      { number: 6, text: "Was sonst noch über die Herrschaft von Asarja zu sagen ist, über seine Taten und Erfolge, findet man in der Chronik der Könige von Juda." },
      { number: 7, text: "Als Asarja starb, wurde er in der Grabstätte seiner Väter in der Davidsstadt bestattet und sein Sohn Jotam trat die Herrschaft an." },
      { number: 8, text: "Im 38. Jahr des Königs Asarja von Juda wurde Secharja Ben-Jerobeam König über Israel. Er regierte sechs Monate lang in Samaria.", heading: "Secharja von Israel" },
      { number: 9, text: "Wie seine Vorfahren tat er, was Jahwe verabscheute. Von dem sündhaften Gottesdienst, zu dem Jerobeam Ben-Nebat Israel verführt hatte, ließ er nicht ab." },
      { number: 10, text: "Schallum Ben-Jabesch zettelte eine Verschwörung gegen ihn an und erschlug ihn in aller Öffentlichkeit. Er wurde sein Nachfolger." },
      { number: 11, text: "Was sonst noch über die Herrschaft Secharjas zu sagen ist, findet man in der Chronik der Könige von Israel." },
      { number: 12, text: "Damit erfüllte sich die Zusage Jahwes an Jehu: \"Deine Nachkommen werden bis in die vierte Generation auf dem Thron Israels sitzen.\" So war es auch geschehen." },
      { number: 13, text: "Schallum Ben-Jabesch wurde im 39. Regierungsjahr des Königs Usija von Juda König und regierte einen Monat lang in Samaria.", heading: "Schallum von Israel" },
      { number: 14, text: "Da zog Menahem Ben-Gadi aus der Stadt Tirza* nach Samaria herauf, drang in die Stadt ein, erschlug Schallum und wurde selbst König.", footnotes: ["Tirza war berühmt für ihre Schönheit und Sitz einer Garnison. Die Stadt lag 12 km östlich von Samaria."] },
      { number: 15, text: "Was sonst noch über die Herrschaft Schallums und seine Verschwörung zu sagen ist, findet man in der Chronik der Könige von Israel." },
      { number: 16, text: "Von Tirza aus zog Menahem gegen die Stadt Tifsach*, weil sie sich ihm nicht unterworfen hatte. Er richtete ein Blutbad unter ihren Bewohnern an; allen Schwangeren ließ er den Leib aufschlitzen.", footnotes: ["Tifsach. Es gab mehrere Orte dieses Namens. Einer davon liegt etwa 20 km südlich von Samaria. Möglicherweise hatten die Anhänger Schallums sich in diese Stadt zurückgezogen."] },
      { number: 17, text: "Im 39. Regierungsjahr des Königs Usija von Juda wurde Menahem Ben-Gadi König über Israel und regierte zehn Jahre in Samaria.", heading: "Menahem von Israel" },
      { number: 18, text: "Er tat sein Leben lang, was Jahwe verabscheute. Von dem sündhaften Gottesdienst, zu dem Jerobeam Ben-Nebat Israel verführt hatte, ließ er nicht ab." },
      { number: 19, text: "Als König Tiglat-Pileser* von Assyrien gegen Israel anrückte, zahlte ihm Menahem 35 Tonnen Silber*, damit dieser seine Herrschaft über Israel bestätigte.", footnotes: ["Tiglat-Pileser. Wörtlich:Pul. So nannte sich Tiglat-Pileser III. (745-727 v.Chr.) seit der Eroberung Babylons, wie eine babylonische und eine ägyptische Königsliste bezeugen.", "35 Tonnen Silber. Wörtlich: 1000 Talente. Das sind drei Millionen Schekel (Silberstücke zu je 11,5 Gramm)."] },
      { number: 20, text: "Das Geld brachte er zusammen, indem er allen vermögenden Leuten in Israel eine Steuer von einem halben Kilogramm* Silber auferlegte. Daraufhin zog der König von Assyrien aus Israel ab.", footnotes: ["halbes Kilogramm. Wörtlich: fünfzig Schekel."] },
      { number: 21, text: "Was sonst noch über Menahems Herrschaft zu sagen ist, findet man in der Chronik der Könige von Israel." },
      { number: 22, text: "Als Menahem starb, wurde sein Sohn Pekachja König." },
      { number: 23, text: "Im 50. Regierungsjahr des Königs Asarja von Juda wurde Pekachja Ben-Menahem König über Israel. Er regierte zwei Jahre* in Samaria", heading: "Pekachja von Israel", footnotes: ["zwei Jahre. 742-740 v.Chr."] },
      { number: 24, text: "und tat, was Jahwe verabscheute. Von dem sündhaften Gottesdienst, zu dem Jerobeam Ben-Nebat Israel verführt hatte, ließ er nicht ab." },
      { number: 25, text: "Sein Adjutant Pekach Ben-Remalja zettelte eine Verschwörung gegen ihn an und erschlug ihn im Wohnturm des Königspalastes von Samaria*. Unterstützt wurde er dabei von 50 Männern aus Gilead. Er tötete ihn und wurde König an seiner Stelle.", footnotes: ["Samaria. Im Hebräischen folgt hier: \"Argob und Arje\". Die Begriffe sind bis heute nicht geklärt. Man kann sie als Personen, möglicherweise Prinzen, oder als Ortsnamen auffassen."] },
      { number: 26, text: "Was sonst noch über Pekachjas Herrschaft zu sagen ist, findet man in der Chronik der Könige von Israel." },
      { number: 27, text: "Im 52. Regierungsjahr* des Königs Asarja von Juda wurde Pekach Ben-Remalja König über Israel und regierte insgesamt 20 Jahre in Samaria*.", heading: "Pekach von Israel", footnotes: ["52. Regierungsjahr. 740 v.Chr.", "20 Jahre in Samaria. Dabei sind die Jahre einer Gegenregierung ab 752 v.Chr. in Gilead mitgezählt. Er regierte bis 732 v.Chr."] },
      { number: 28, text: "Er tat, was Jahwe verabscheute, und ließ nicht von dem sündhaften Gottesdienst ab, zu dem Jerobeam Ben-Nebat Israel verführt hatte." },
      { number: 29, text: "Während Pekachs Regierungszeit fiel der Assyrerkönig Tiglat-Pileser in Israel ein. Er eroberte die Städte Ijon, Abel-Bet-Maacha, Janoach, Kedesch und Hazor*, sowie die Landschaften Gilead und Galiläa und das ganze Stammesgebiet Naftalis. Die Bewohner dieser Gebiete verschleppte er nach Assyrien*.", footnotes: ["... Hazor. Das sind Städte in Nordgaliläa.", "nach Assyrien. Diese erste Deportation der Israeliten fand um das Jahr 733 v.Chr. statt."] },
      { number: 30, text: "Hoschea Ben-Ela zettelte eine Verschwörung gegen Pekach Ben-Remalja an. Er erschlug ihn und wurde an seiner Stelle König. Das geschah im 20. Regierungsjahr von König Jotam Ben-Usija." },
      { number: 31, text: "Was sonst noch über Pekachs Herrschaft zu sagen ist, findet man in der Chronik der Könige von Israel." },
      { number: 32, text: "Im zweiten Regierungsjahr des Königs Pekach Ben-Remalja von Israel wurde Jotam Ben-Usija Mitregent von Juda.", heading: "Jotam von Juda" },
      { number: 33, text: "Er war damals 25 Jahre alt und regierte insgesamt 16 Jahre in Jerusalem*. Seine Mutter hieß Jeruscha und war eine Tochter Zadoks.", footnotes: ["... Jerusalem. Von 750-740 war Jotam Mitregent neben seinem aussätzigen Vater Usija (in V. 15,1 ff. Asarja genannt). Allein regierte er bis 735 v.Chr."] },
      { number: 34, text: "Er tat, was Jahwe gefiel, und folgte in allem dem Vorbild seines Vaters Usija." },
      { number: 35, text: "Die Opferstätten auf den Höhen ließ er allerdings bestehen, sodass das Volk dort auch weiterhin Schlacht- und Räucheropfer brachte. Jotam war es, der das obere Tor am Haus Jahwes baute." },
      { number: 36, text: "Was sonst noch über Jotams Herrschaft zu sagen ist, findet man in der Chronik der Könige von Juda." },
      { number: 37, text: "Damals begann Jahwe die Könige Rezin von Syrien und Pekach Ben-Remalja gegen Juda loszuschicken." },
      { number: 38, text: "Als Jotam starb, wurde er in der Grabstätte seiner Väter in der Davidsstadt bestattet und sein Sohn Ahas trat die Herrschaft an." },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Im 17. Regierungsjahr von Pekach Ben-Remalja wurde Ahas Ben-Jotam König über Juda.", heading: "Ahas von Juda" },
      { number: 2, text: "Er war damals 20 Jahre alt* und regierte nach dem Tod Jotams* 16 Jahre in Jerusalem. Er handelte nicht nach dem Vorbild seines Vorfahren David und tat nicht, was Jahwe gefiel,", footnotes: ["20 Jahre alt. Das war 735 v.Chr. Er war zunächst Mitregent.", "Nach dem Tod Jotams ist eingefügt. Die 16 Jahre der Regierungszeit von Ahas (= Kurzform von Joahas) rechnen sich wohl erst nach dem Tod seines Vaters Jotam (732-716 v.Chr.), denn sonst wäre Ahas bei der Geburt seines Sohnes erst 11 Jahre alt gewesen."] },
      { number: 3, text: "sondern folgte dem schlechten Beispiel der Könige von Israel. Er ließ sogar einen seiner Söhne als Opfer verbrennen, wie es der grauenvollen Gewohnheit der heidnischen Völker entsprach, die Jahwe vor den Israeliten aus dem Land vertrieben hatte." },
      { number: 4, text: "Außerdem brachte er an den Opferstätten auf den Höhen und unter jedem grünen Baum Schlacht- und Räucheropfer dar." },
      { number: 5, text: "Damals zogen König Rezin von Syrien und König Pekach Ben-Remalja von Israel gegen Jerusalem, um die Stadt zu belagern.* Doch es kam nicht zum Kampf.", footnotes: ["zu belagern. Das war gleich, nachdem Ahas Mitregent geworden war, 735 oder 734 v.Chr"] },
      { number: 6, text: "Rezin konnte in dieser Zeit jedoch Elat* wieder unter syrische Kontrolle bringen. Er vertrieb die Juden aus der Stadt. Später kamen die Edomiter nach Elat zurück und machten sich dort sesshaft. So ist es bis heute geblieben.", footnotes: ["Elat. Siehe 14,21."] },
      { number: 7, text: "Ahas schickte Boten an König Tiglat-Pileser von Assyrien und ließ ihm ausrichten: \"Ich unterwerfe mich dir und stelle mich unter deinen Schutz. Die Könige von Syrien und Israel greifen mich an. Komm doch und rette mich aus ihrer Gewalt!\"" },
      { number: 8, text: "Zugleich ließ Ahas dem Assyrerkönig alles Silber und Gold überbringen, das sich im Haus Jahwes und den Schatzkammern des Königs befand." },
      { number: 9, text: "Der König von Assyrien hörte auf die Bitte des Ahas und zog gegen Damaskus. Er eroberte die Stadt und führte ihre Bewohner nach Kir* in die Verbannung. König Rezin tötete er.", footnotes: ["Kir. Ort in Mesopotamien, Identität unbekannt."] },
      { number: 10, text: "Da zog König Ahas nach Damaskus, um dort mit Tiglat-Pileser zusammenzutreffen. Als er den Altar in der Stadt sah, schickte er dem Priester Urija ein Modell samt einer genauen Beschreibung davon." },
      { number: 11, text: "Nach diesen Angaben baute Urija einen Altar und hatte ihn fertig, bevor der König aus Damaskus zurückkam." },
      { number: 12, text: "Als Ahas dann wieder in Jerusalem war, sah er sich den Altar an. Er stieg die Stufen hinauf" },
      { number: 13, text: "und brachte selbst die ersten Opfer dar. Er ließ sein Brand- und Speisopfer in Rauch aufgehen, goss ein Trankopfer aus und sprengte das Blut der Tiere, die für die Opfermahlzeit geschlachtet wurden, an die Wand des Altars." },
      { number: 14, text: "Den Bronzealtar, der vor Jahwe stand, ließ er von der Vorderseite des Hauses wegrücken – er stand zwischen dem Haus Jahwes und dem neuen Altar – und auf der Nordseite rechts neben dem neuen Altar aufstellen." },
      { number: 15, text: "Dem Priester Urija befahl er: \"Auf dem großen neuen Altar werden von jetzt an alle Brand- und Speisopfer dargebracht, die Morgen- und Abendopfer, ebenso die Brand-, Speis- und Trankopfer für den König und das ganze Volk. Und alles Blut der Tiere, die für Brand- und Freudenopfer* geschlachtet werden, soll an diesen Altar gesprengt werden. Den Bronzealtar will ich benutzen, um dort die Opferschau* vorzunehmen.\"", footnotes: ["Beim Freudenopfer wurde im Gegensatz zum Brandopfer nur das Fett auf dem Altar verbrannt. Der größte Teil des Tieres durfte bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden.", "Opferschau. Ein heidnischer Ritus, bei dem aus der Betrachtung der Eingeweide eines Opfertiers günstige oder ungünstige Vorzeichen herausgelesen wurden."] },
      { number: 16, text: "Der Priester Urija ließ alles nach Anordnung des Königs ausführen." },
      { number: 17, text: "König Ahas ließ auch die Leisten und die Kessel von den bronzenen Kesselwagen aus dem Tempel entfernen. Ebenso ließ er die zwölf Bronzerinder unter dem großen runden Becken, dem sogenannten \"Meer\", wegnehmen und dieses auf einen Unterbau aus Stein setzen." },
      { number: 18, text: "Auch die Sabbathalle, die man am Haus Jahwes gebaut hatte, und den besonderen Eingang für den König ließ er mit Rücksicht auf den assyrischen König abreißen." },
      { number: 19, text: "Was sonst noch über die Herrschaft des Ahas zu sagen ist, findet man in der Chronik der Könige von Juda." },
      { number: 20, text: "Als er starb, wurde er in der Grabstätte seiner Vorfahren in der Davidsstadt beigesetzt und sein Sohn Hiskija trat die Herrschaft an." },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Im zwölften Regierungsjahr des Königs Ahas von Juda wurde Hoschea Ben-Ela König über Israel und regierte neun Jahre* in Samaria.", heading: "Hoschea von Israel", footnotes: ["neun Jahre. 732-722 v.Chr."] },
      { number: 2, text: "Er tat, was Jahwe verabscheute, doch nicht so schlimm wie seine Vorgänger." },
      { number: 3, text: "Als König Salmanassar von Assyrien mit einem Heer gegen ihn zog, unterwarf sich Hoschea und zahlte Tribut." },
      { number: 4, text: "Aber der Assyrerkönig entdeckte, dass Hoschea sich gegen ihn verschworen hatte, denn dieser hatte Boten an König So* von Ägypten geschickt und die Tributzahlungen eingestellt. Daraufhin ließ Salmanassar ihn verhaften und ins Gefängnis werfen.", footnotes: ["So. Vielleicht Osorkon IV., etwa 727 – 716 v.Chr."] },
      { number: 5, text: "Er war nämlich mit seinem Heer ins Land eingefallen und hatte Samaria belagert. Im dritten Jahr der Belagerung," },
      { number: 6, text: "dem neunten Regierungsjahr Hoscheas, eroberte der Assyrer die Stadt und verschleppte* die Bevölkerung Israels nach Assyrien. Dort siedelte er sie in der Provinz Halach* an, am Fluss Habor*, in der Provinz Gosan und in den Städten Mediens*.", footnotes: ["verschleppte. Diese zweite Deportation der Israeliten fand im Jahr 722 v.Chr. statt.", "Halach. Die Lage der Provinz ist unbekannt.", "Habor. Es handelt sich um den Fluss Khabur, einen von Norden kommenden Nebenfluss des Euphrat.", "Die Städte Mediens lagen im Gebiet östlich von Ninive und südlich des Kaspischen Meeres."] },
      { number: 7, text: "Das alles geschah, weil die Israeliten gegen Jahwe, ihren Gott, gesündigt hatten, der sie aus Ägypten herausgeführt und aus der Gewalt des Pharao befreit hatte. Sie verehrten andere Götter", heading: "Israels Schuld an seiner Wegführung" },
      { number: 8, text: "und übernahmen die heidnischen Bräuche der Völker, die Jahwe vor ihnen aus dem Land vertrieben hatte, und die Gottesdienste, die von den Königen Israels eingeführt worden waren." },
      { number: 9, text: "Sie erdachten sich gegen den Willen von Jahwe, ihrem Gott, eigene Gottesdienste. Sie richteten überall Höhenheiligtümer ein, vom einsamen Wachtturm bis zur befestigten Stadt." },
      { number: 10, text: "Auf jedem höheren Hügel und unter jedem größeren Baum stellten sie geweihte Steinmale und Aschera-Pfähle auf." },
      { number: 11, text: "Dort verbrannten sie Opfergaben wie die Völker, die Jahwe vor ihnen vertrieben hatte. Sie taten böse Dinge und forderten den Zorn Jahwes heraus." },
      { number: 12, text: "Sie verehrten diese Mistgötzen*, obwohl Jahwe ihnen das ausdrücklich untersagt hatte.", footnotes: ["Mistgötzen. Wörtlich:Mistkugel, eine bewusst verächtliche Bezeichnung für die Götzenbilder."] },
      { number: 13, text: "Außerdem hatte Jahwe Israel und Juda durch seine Propheten und Seher immer wieder gewarnt. \"Kehrt um von euren bösen Wegen!\", hatte er ihnen gesagt. \"Haltet meine Gebote! Richtet euch nach den Vorschriften meines Gesetzes, das ich euren Vorfahren gab, und das ich euch durch meine Propheten, die mir dienen, immer wieder ausrichten ließ.\"" },
      { number: 14, text: "Aber sie wollten nicht hören und zeigten sich genauso halsstarrig wie ihre Väter, die Jahwe, ihrem Gott, kein Vertrauen geschenkt hatten." },
      { number: 15, text: "Sie verachteten seine Vorschriften, verwarfen den Bund, den er mit ihren Vätern geschlossen hatte, und schlugen seine Warnungen in den Wind. Den Nichtsen liefen sie hinterher und wurden dabei selbst zu Nichts. Sie trieben es wie ihre Nachbarvölker, obwohl Jahwe ihnen das verboten hatte." },
      { number: 16, text: "Die Gebote Jahwes, ihres Gottes, missachteten sie. Sie fertigten sich zwei gegossene Stierbilder an und stellten der Aschera geweihte Pfähle auf. Sie verehrten das Heer der Sterne am Himmel und dienten dem Götzen Baal." },
      { number: 17, text: "Ihre eigenen Kinder ließen sie als Opfer für die Götzen verbrennen. Sie trieben Wahrsagerei und Zauberei und gaben sich dazu her, alles zu tun, was Jahwe verabscheute und ihn beleidigen musste." },
      { number: 18, text: "Da wurde Jahwe so zornig über die Israeliten, dass er sie aus seiner Nähe vertrieb und nur noch den Stamm Juda im Land wohnen ließ." },
      { number: 19, text: "Aber auch die Judäer missachteten die Gebote Jahwes, ihres Gottes, und folgten den Ordnungen, die die Israeliten eingeführt hatten." },
      { number: 20, text: "Da verstieß Jahwe die ganze Nachkommenschaft Israels. Er demütigte sie und ließ sie von fremden Heeren ausplündern, bis er sie aus seiner Nähe weggeschafft hatte." },
      { number: 21, text: "Jahwe selbst hatte nämlich Israel vom Königshaus David losgerissen, und die Israeliten hatten Jerobeam Ben-Nebat zum König gemacht. Jerobeam aber hatte sie dazu gebracht, sich von Jahwe abzuwenden, und sie so zu einer schweren Sünde verführt." },
      { number: 22, text: "Die Israeliten verfielen dem sündhaften Gottesdienst, den Jerobeam eingeführt hatte, und wollten nicht davon lassen," },
      { number: 23, text: "bis Jahwe sie aus seiner Nähe vertrieb. Das hatte er ihnen durch alle seine Propheten, die ihm dienten, immer wieder ankündigen lassen. Schließlich wurden die Israeliten aus ihrem Land nach Assyrien weggeführt. Das ist bis heute* noch so.", footnotes: ["bis heute. Vom Standpunkt der Verfasser der Königsbücher aus."] },
      { number: 24, text: "Der König von Assyrien ließ nun Leute aus den Städten Babylon, Kuta, Awa, Hamat und Sefarwajim* kommen. Sie nahmen anstelle der Israeliten das Land Samaria und seine Städte in Besitz.", heading: "Samaria wird wieder besiedelt", footnotes: ["... Sefarwajim. Die genannten Städte lagen (außer Babylon) wahrscheinlich alle in Syrien um Hamat am Orontes herum."] },
      { number: 25, text: "In der ersten Zeit, als sie dort wohnten, verehrten sie Jahwe nicht. Deshalb ließ Jahwe Löwen in die Gegend kommen, die viele Menschen töteten." },
      { number: 26, text: "Dem König von Assur wurde gemeldet: \"Die Leute, die du aus ihrem Land weggeführt und in Samarien angesiedelt hast, wissen nicht, auf welche Weise der Gott dieses Landes verehrt werden will. Deshalb hat er Löwen unter sie geschickt, die schon viele von ihnen getötet haben. Und das nur, weil sie nicht wissen, wie der Gott dieses Landes verehrt werden muss.\"" },
      { number: 27, text: "Da befahl der Assyrerkönig: \"Schickt einen der Priester, die ihr von dort weggeführt habt, in seine Heimat zurück! Er soll bei den Leuten dort wohnen und ihnen beibringen, wie der Gott dieses Landes verehrt werden will!\"" },
      { number: 28, text: "So kam einer der Priester, die man aus Samaria gefangen weggeführt hatte, zurück und ließ sich in Bet-El nieder. Er zeigte den Leuten, wie sie Jahwe verehren sollten." },
      { number: 29, text: "Aber die Siedler hielten weiterhin auch an ihren eigenen Göttern fest. Sie machten sich Götzenbilder und stellten sie in den vielen Höhenheiligtümern auf, die die Samaritaner überall errichtet hatten. Jede Volksgruppe hatte ihren eigenen Gott:" },
      { number: 30, text: "Die Leute aus Babylon errichteten eine Statue von Sukkot-Benot, die Leute aus Kuta stellten Nergal auf und die aus Hamat eine Aschima." },
      { number: 31, text: "Die Leute aus Awa stellten Bilder der Götter Nibhas und Tartak auf, und die aus Sefarwajim verbrannten sogar ihre eigenen Kinder als Opfer für Adrammelech und Anammelech, ihre heimischen Götter." },
      { number: 32, text: "Daneben verehrten sie aber auch Jahwe und setzten aus ihren eigenen Reihen Priester ein, die den Opferdienst in den Höhenheiligtümern versahen." },
      { number: 33, text: "So verehrten sie Jahwe, dienten aber gleichzeitig ihren eigenen Göttern. Sie hielten an den Bräuchen ihrer Heimat fest, aus der man sie vertrieben hatte." },
      { number: 34, text: "So machen sie es bis heute. Sie verehren Jahwe nicht wirklich, denn sie richten sich keineswegs nach seinen Anweisungen und Ordnungen. Sie kümmern sich nicht um das Gesetz, das Jahwe den Nachkommen Jakobs gegeben hat, des Jakob, den er später Israel nannte." },
      { number: 35, text: "Mit seinen Nachkommen hatte Jahwe nämlich einen Bund geschlossen und sie dabei ausdrücklich angewiesen: \"Ihr dürft keine fremden Götter verehren! Werft euch nicht vor ihnen nieder, dient ihnen nicht und bringt ihnen keine Opfer!" },
      { number: 36, text: "Dient allein Jahwe, der euch mit großer Kraft und ausgestrecktem Arm aus Ägypten herausgeführt hat! Ihn sollt ihr verehren, vor ihm euch niederwerfen und ihm eure Opfer bringen!" },
      { number: 37, text: "Die Ordnungen und Rechtsbestimmungen, die Weisungen und Gebote, die er für euch aufgeschrieben hat, sollt ihr jeden Tag sorgfältig beachten! Verehrt keine fremden Götter!" },
      { number: 38, text: "Denkt an den Bund, den ich mit euch geschlossen habe, und fürchtet keine fremden Götter," },
      { number: 39, text: "sondern verehrt allein Jahwe, euren Gott! Nur er wird euch aus der Gewalt aller eurer Feinde retten.\"" },
      { number: 40, text: "Doch sie wollten nicht hören und hielten an ihren früheren Bräuchen fest." },
      { number: 41, text: "So fürchteten diese Stämme zwar Jahwe, zugleich aber auch ihre Götzen. Ihre Kinder und Enkel machten es genauso. Und so ist es bis heute geblieben." },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Im dritten Regierungsjahr des Königs Hoschea Ben-Ela von Israel wurde Hiskija Ben-Ahas Mitregent* von Juda.", heading: "18-25: Das Südreich Juda\nDer gute König Hiskija (18-20)\nHiskija von Juda", footnotes: ["Mitregent. Wörtlich: König. Das war 729 v. Chr. Damals war er erst 11 Jahre alt."] },
      { number: 2, text: "Als er König wurde, war er 25 Jahre alt und regierte 29 Jahre* in Jerusalem. Seine Mutter hieß Abi und war eine Tochter Secharjas.", footnotes: ["29 Jahre. Von 715-686 v.Chr."] },
      { number: 3, text: "Wie sein Vorfahr David tat Hiskija, was Jahwe gefiel." },
      { number: 4, text: "Er beseitigte die Opferstätten auf den Höhen, ließ die geweihten Steinmale zerschlagen und das Pfahlbild der Aschera umhauen. Auch die Bronzeschlange, die Mose einst angefertigt hatte, schlug er in Stücke. Denn bis zu dieser Zeit hatten die Israeliten immer wieder Weihrauch vor ihr verbrannt. Man nannte sie Nehuschtan*.", footnotes: ["In Nehuschtan klingen die hebräischen Worte für Bronze, Schlange und Unreinheit an."] },
      { number: 5, text: "Hiskija vertraute auf Jahwe, den Gott Israels, wie kein König von Juda vor oder nach ihm." },
      { number: 6, text: "Sein Leben lang hielt er treu an Jahwe fest und befolgte die Gebote, die Jahwe Mose gegeben hatte." },
      { number: 7, text: "So war denn auch Jahwe mit ihm und gab ihm Erfolg in allem, was er unternahm. Es gelang ihm auch, sich von der Herrschaft des Königs von Assyrien zu befreien." },
      { number: 8, text: "Er schlug die Philister bis nach Gaza zurück und verwüstete die ganze Gegend vom Wachtturm bis zur befestigten Stadt." },
      { number: 9, text: "Im vierten Regierungsjahr Hiskijas – es war das siebte Jahr des Königs Hoschea Ben-Ela von Israel – zog König Salmanassar von Assyrien nach Samaria und belagerte die Stadt.", heading: "Die Assyrer erobern Samaria" },
      { number: 10, text: "Nach fast drei Jahren eroberte er sie. Das war im sechsten Regierungsjahr Hiskijas und im neunten Hoscheas." },
      { number: 11, text: "Der Assyrerkönig verschleppte die Bevölkerung Israels nach Assyrien und siedelte sie in der Provinz Halach an, am Fluss Habor, in der Provinz Gosan und in den Städten Mediens." },
      { number: 12, text: "Das alles geschah, weil die Israeliten nicht auf Jahwe, ihren Gott, gehört hatten. Sie brachen seinen Bund und befolgten die Gebote nicht mehr, die Mose, der Diener Gottes, ihnen verkündet hatte." },
      { number: 13, text: "Im 14. Regierungsjahr* Hiskijas marschierte der assyrische König Sanherib* in Juda ein und eroberte alle befestigten Städte*.", heading: "Assyrer vor Jerusalem", footnotes: ["Das war 701 v.Chr., im 14. Regierungsjahr seiner Alleinregierung. Hiskija war von 729 v.Chr. an Mitregent und regierte von 715-686 allein.", "Sanherib war von 705-681 v.Chr. König von Assyrien.", "... Städte. In seinen Annalen rühmte sich Sanherib, 46 befestigte Städte in Juda eingenommen, zahllose Dörfer erobert und mehr als 200.000 Gefangene gemacht zu haben. Er habe Hiskija zu einem \"Gefangenen in Jerusalem, seiner eigenen Residenz, gemacht wie einen Vogel im Käfig\"."] },
      { number: 14, text: "Da schickte König Hiskija Boten zum Assyrerkönig, der mit seinem Heer vor Lachisch* stand, und ließ ihm ausrichten: \"Ich habe einen schweren Fehler gemacht. Zieh bitte aus meinem Land wieder ab! Ich will auch alles tragen, was du mir auferlegst!\" Der Assyrerkönig forderte einen Tribut von zehn Tonnen Silber und einer Tonne* Gold.", footnotes: ["Lachisch. Stadt im Hügelland, 46 km südwestlich von Jerusalem. Sie wurde von König Rehabeam zur Festung ausgebaut.", "... Tonne. Wörtlich: 300 Talente Silber und 30 Talente Gold."] },
      { number: 15, text: "Hiskija musste ihm alles Silber abliefern, das sich im Haus Jahwes und in den Schatzkammern des Königs befand." },
      { number: 16, text: "Außerdem ließ er damals das Goldblech an den Türen und Pfosten vom Haus Jahwes abreißen, die er selbst erst hatte überziehen lassen, und übergab es dem Assyrerkönig." },
      { number: 17, text: "Doch dieser schickte von Lachisch aus den Tartan, seinen obersten Feldherrn, zusammen mit dem Rabsaris und dem Rabschake, seinen höchsten Würdenträgern, mit einem gewaltigen Heer zu Hiskija nach Jerusalem. Die Würdenträger stellten sich an der Straße auf, die zu dem Feld führt, wo die Tuchmacher ihre Stoffe bleichen, an das Ende der Wasserleitung beim oberen Teich." },
      { number: 18, text: "Dort riefen sie nach dem König. Da kamen Eljakim Ben-Hilkija, der Palastvorsteher, der Staatsschreiber Schebna und der Kanzler Joach Ben-Asaf zu ihnen heraus." },
      { number: 19, text: "Der Rabschake trug ihnen eine Botschaft an Hiskija auf:\"Der Großkönig, der König von Assyrien, lässt dir sagen: Worauf vertraust du eigentlich, dass du dich so sicher fühlst?" },
      { number: 20, text: "Meinst du, der Ausgang eines Krieges wird von Worten bestimmt? Auf wen vertraust du denn, dass du es wagst, gegen mich zu rebellieren?" },
      { number: 21, text: "Verlässt du dich etwa auf Ägypten, dieses zerbrochene Bambusrohr, das jedem die Hand verletzt, der sich darauf stützt? Der Pharao von Ägypten ließ noch jeden im Stich, der sich auf ihn verließ." },
      { number: 22, text: "Vielleicht wirst du jetzt behaupten: Wir vertrauen auf Jahwe, unseren Gott! Aber hat Hiskija nicht gerade dessen Höhenheiligtümer und Altäre beseitigt? Hat er nicht den Leuten in Juda und Jerusalem befohlen, nur noch vor dem einen Altar anzubeten? –" },
      { number: 23, text: "Mein Herr, der König von Assyrien, bietet dir eine Wette an: 'Ich will dir 2000 Pferde geben, wenn du die Reiter dazu stellen kannst!'" },
      { number: 24, text: "Wie willst du auch nur einen einzigen Provinzstatthalter vertreiben, einen der geringsten Diener meines Herrn? Aber du verlässt dich ja auf die Macht der ägyptischen Pferde und Streitwagen!" },
      { number: 25, text: "Und noch etwas: Bin ich etwa gegen den Willen Jahwes in dieses Land einmarschiert, um es in Schutt und Asche zu legen? Jahwe selbst hat mir gesagt: Greif dieses Land an und verwüste es!\"" },
      { number: 26, text: "Da unterbrachen Eljakim, Schebna und Joach den Würdenträger und baten ihn: \"Sprich doch bitte aramäisch mit uns! Wir verstehen es. Sprich nicht hebräisch! Die Leute auf der Stadtmauer hören uns zu.\"" },
      { number: 27, text: "Doch der Rabschake erwiderte: \"Hat mich mein Herr etwa nur zu dir und deinem Herrn gesandt? Nein, gerade diese Männer, die da oben auf der Mauer sitzen, sollen es hören. Denn bald werden sie zusammen mit euch ihren eigenen Kot fressen und ihren Harn saufen.\"" },
      { number: 28, text: "Da trat der Rabschake noch ein Stück vor und rief laut auf Hebräisch: \"Hört, was der Großkönig, der König von Assyrien, euch sagen lässt:" },
      { number: 29, text: "Lasst euch nicht von Hiskija täuschen! Er kann euch nicht retten." },
      { number: 30, text: "Lasst euch von ihm auch nicht auf Jahwe vertrösten: 'Jahwe wird uns bestimmt retten; diese Stadt wird dem Assyrerkönig nicht in die Hände fallen!'" },
      { number: 31, text: "Hört nicht auf Hiskija! Denn der König von Assyrien sagt euch: Kommt heraus und ergebt euch mir! Dann kann jeder von seinem Weinstock und Feigenbaum essen und aus seiner Zisterne trinken," },
      { number: 32, text: "bis ich euch in ein Land bringe, das ebenso gut wie eures ist, wo es Korn und Most, Brot und Weinberge gibt. So werdet ihr am Leben bleiben und nicht umkommen. Lasst euch von Hiskija nicht an der Nase herumführen, wenn er behauptet: 'Jahwe wird uns retten!'" },
      { number: 33, text: "Hat denn irgendein Gott der anderen Völker sein Land vor dem König von Assyrien retten können?" },
      { number: 34, text: "Wo sind denn die Götter von Hamat und Arpad? Wo sind die Götter von Sefarwajim*, Hena* und Awa*? Wo sind die Götter des Landes Samarien? Haben sie etwa Samaria vor mir beschützt?", footnotes: ["Sefarwajim. Ort in Syrien, Lage unbekannt. Die Einwohner wurden von den Assyrern im Norden Israels angesiedelt, siehe 2. Könige 17,24.31.", "Hena. Vermutlich Stadt in Nordsyrien.", "Awa. Stadtstaat in Nordsyrien, aus dem der Assyrerkönig Salmanassar Leute nach Israel umsiedelte, siehe 2. Könige 17,24."] },
      { number: 35, text: "Wer von allen Göttern hat sein Land vor mir retten können? Und dann soll Jahwe Jerusalem vor mir beschützen?\"" },
      { number: 36, text: "Die Männer auf der Mauer schwiegen und gaben ihm keine Antwort, wie es der König befohlen hatte." },
      { number: 37, text: "Die drei Unterhändler gingen mit eingerissenen Gewändern zu Hiskija und berichteten ihm, was der Rabschake gesagt hatte." },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Als der König das hörte, riss er sein Obergewand ein, zog den Trauersack an und ging ins Haus Jahwes.", heading: "Jahwe ermutigt Hiskija" },
      { number: 2, text: "Dann schickte er den Palastvorsteher Eljakim und den Staatsschreiber Schebna mit den Ältesten der Priesterschaft, ebenfalls im Trauersack, zu dem Propheten Jesaja Ben-Amoz." },
      { number: 3, text: "Im Namen des Königs sollten sie ihm sagen: \"Heute ist ein schrecklicher Tag, wir sind gezüchtigt und geschmäht. Die Kinder sind bis an den Muttermund gekommen, aber zum Gebären ist keine Kraft mehr da." },
      { number: 4, text: "Wenn doch Jahwe, dein Gott, die Worte des Rabschake hören wollte, den der König von Assyrien geschickt hat, um ihn, den lebendigen Gott, zu verhöhnen. Vielleicht bestraft er den König wegen dieser Worte, die er gehört hat. Bete doch für die, die von Gottes Volk noch übrig geblieben sind.\"" },
      { number: 5, text: "Die Männer des Königs kamen zu Jesaja und erhielten folgende Antwort:" },
      { number: 6, text: "\"Sagt eurem Herrn: 'So spricht Jahwe: Hab keine Angst vor den Drohungen, die du gehört hast! Fürchte dich nicht vor den Lästerungen der Boten des assyrischen Königs!" },
      { number: 7, text: "Pass auf, ich werde dafür sorgen, dass er ein Gerücht hört und in sein Land zurückkehrt! Dort werde ich ihn umbringen lassen.'\"" },
      { number: 8, text: "Der Rabschake kehrte zu seinem König zurück. Er hatte erfahren, dass dieser von Lachisch aufgebrochen war und inzwischen gegen Libna kämpfte." },
      { number: 9, text: "Sein König hatte nämlich gehört, dass der nubische* König Tirhaka* mit einem Heer gegen ihn heranrücken würde. Deshalb schickte er wieder Boten zu Hiskija", footnotes: ["Nubien. Land am Oberlauf des Nil.", "Der 20-jährige Tirhaka wird elf Jahre später König von Ägypten sein (690-664)."] },
      { number: 10, text: "und ließ ihm ausrichten: \"Lass dich von deinem Gott nicht täuschen, auch wenn du ihm vertraust! Denke nicht, dass Jerusalem dem König von Assyrien niemals in die Hände fällt!" },
      { number: 11, text: "Du hast ja gehört, was die Könige von Assyrien mit all den anderen Ländern gemacht haben, an denen sie den Bann* vollstreckten. Und da willst ausgerechnet du verschont bleiben?", footnotes: ["Bann. Das bedeutete die vollständige Vernichtung von Menschen, Tieren und Gütern."] },
      { number: 12, text: "Haben die Götter der Völker, die meine Vorfahren vernichtet haben, ihre Nationen etwa retten können: Gosan*, Haran*, Rezef* und die Bevölkerung Edens* in Telassar*?", footnotes: ["Gosan. Stadt in Nordmesopotamien, in die einige Israeliten von den Assyrern deportiert worden waren.", "Haran. Stadt, westlich von Gosan, in der Abraham einige Jahre lebte, siehe 1. Mose 11,31.", "Rezef. Stadt zwischen Haran und dem Euphrat.", "Eden. Aramäisches Fürstentum in der Nähe des oberen Euphrat-Tals.", "Telassar. Noch nicht identifizierte Stadt in Eden zwischen den Flüssen Euphrat und Balich."] },
      { number: 13, text: "Wo sind denn die Könige, die in Hamat und Arpad regierten? Wo sind die Könige von Sefarwajim, Hena und Awa?\"" },
      { number: 14, text: "Hiskija nahm das Schreiben der Boten in Empfang und las es. Dann ging er in den Tempel, breitete es vor Jahwe aus" },
      { number: 15, text: "und betete: \"Jahwe, du allmächtiger Gott Israels, der über den Cherubim* thront, du allein bist Gott und Herr über alle Reiche der Welt. Du hast Himmel und Erde geschaffen.", footnotes: ["Cherubim. Majestätische (Engel-)Wesen, die Gottes Herrlichkeit repräsentieren. Geschnitzte Abbilder von ihnen breiteten ihre Flügel über die Bundeslade Israels aus und bildeten im Tempel die sichtbare Basis für den unsichtbaren Thron Gottes."] },
      { number: 16, text: "Schenk mir Gehör, Jahwe! Sieh doch, wie es uns geht! Hör doch, wie Sanherib dich, den lebendigen Gott, verhöhnt!" },
      { number: 17, text: "Es ist wahr, Jahwe, die Könige von Assyrien haben alle diese Länder verwüstet." },
      { number: 18, text: "Sie haben deren Götter ins Feuer geworfen. Aber das waren ja keine Götter, sondern Machwerke aus Holz und Stein. Die konnten sie vernichten." },
      { number: 19, text: "Doch jetzt, Jahwe, unser Gott, rette uns vor ihm, damit alle Königreiche der Welt erkennen, dass du, Jahwe, allein Gott bist.\"" },
      { number: 20, text: "Da ließ Jesaja Ben-Amoz Hiskija ausrichten: \"So spricht Jahwe, der Gott Israels: Ich habe gehört, was du zu mir wegen Sanherib, dem König von Assyrien, gebetet hast." },
      { number: 21, text: "Höre nun, was Jahwe über ihn sagt:'Zion, die unberührte junge Frau, / verachtet dich und spottet über dich, / die Tochter Jerusalem schüttelt den Kopf." },
      { number: 22, text: "Wen hast du verhöhnt und geschmäht, / gegen wen die Stimme erhoben? / Mit wem ließest du dich ein? – Mit Israels heiligem Gott!" },
      { number: 23, text: "Durch deine Boten verhöhntest du ihn. / Du prahlst: Mit den Streitwagen bezwang ich die Berge, / ich stieg bis zum Gipfel des Libanon. / Den Hochwald seiner Zedern habe ich gefällt, / seine schönsten Zypressen dazu. / Ich kam in das entlegenste Versteck, / drang in jedes Dickicht vor." },
      { number: 24, text: "Ich grub nach fremdem Wasser und trank davon. / Mit meiner Fußsohle trocknete ich Ägyptens Flüsse aus." },
      { number: 25, text: "Hast du es nicht gehört? / Schon vor langer Zeit habe ich es gewollt. / Seit uralten Tagen habe ich es geplant, / jetzt ließ ich es kommen, / dass du befestigte Städte zerstörst, / sie zu öden Steinhaufen machst." },
      { number: 26, text: "Machtlos waren ihre Bewohner, / von Schrecken erfüllt. / In Schande sind sie gestoßen. / Sie waren wie Kraut auf dem Feld, / wie grünes Gras, / wie Gras auf den Dächern, / vom Ostwind verdorrt." },
      { number: 27, text: "Ich weiß, ob du ruhst oder gehst oder kommst. / Ich kenne auch dein Toben gegen mich." },
      { number: 28, text: "Und weil du so gegen mich tobst, / ziehe ich dir einen Ring durch die Nase / und lege dir einen Zaum ins Maul / und führe dich auf dem Weg zurück, / auf dem du gekommen bist.'" },
      { number: 29, text: "Und du, Hiskija, wirst daran erkennen, dass es so geschieht: 'In diesem Jahr werdet ihr den Nachwuchs der Ernte essen, im nächsten Jahr den Wildwuchs, aber im dritten Jahr werdet ihr wieder säen und ernten, Weinberge pflanzen und ihre Früchte genießen.'" },
      { number: 30, text: "Und die Bewohner Judas, die mit dem Leben davongekommen sind, werden wieder Wurzeln schlagen und Früchte tragen." },
      { number: 31, text: "Denn ein Rest wird aus Jerusalem kommen, Übriggebliebene vom Berg Zion. Das wird Jahwe, der allmächtige Gott, in seinem Liebeseifer tun." },
      { number: 32, text: "Darum sagt Jahwe Folgendes über den assyrischen König: 'Er wird nicht in diese Stadt eindringen, nicht einen Pfeil wird er hineinschießen. Er wird sie nicht mit Schilden berennen und keinen Wall gegen sie aufschütten." },
      { number: 33, text: "Auf demselben Weg, auf dem er gekommen ist, wird er wieder heimkehren. Er wird ganz bestimmt nicht in diese Stadt eindringen, spricht Jahwe." },
      { number: 34, text: "Um meiner Ehre willen und meinem Diener David zuliebe werde ich diese Stadt retten und beschützen.'\"" },
      { number: 35, text: "In dieser Nacht tötete ein Engel Jahwes im Lager der Assyrer 185.000 Mann. Am nächsten Morgen war alles mit Leichen übersät." },
      { number: 36, text: "Da brach König Sanherib den Feldzug ab und kehrte in seine Heimat nach Ninive zurück." },
      { number: 37, text: "Als er eines Tages im Tempel seines Gottes Nisroch betete, erschlugen ihn seine Söhne Adrammelech und Sarezer mit dem Schwert. Daraufhin mussten sie in das Land Ararat* fliehen, und Sanheribs Sohn Asarhaddon trat die Herrschaft an.", footnotes: ["Land Ararat. Armenien, nördlich von Assyrien."] },
    ] },
    { number: 20, verses: [
      { number: 1, text: "In dieser Zeit wurde Hiskija todkrank.* Da kam der Prophet Jesaja Ben-Amoz zu ihm und sagte: \"Jahwe lässt dir sagen: 'Bereite dich auf dein Ende vor und regle deine Angelegenheiten, du kannst nicht am Leben bleiben!'\"", heading: "Hiskijas Krankheit", footnotes: ["Hiskija todkrank. Dieses Geschehen und der anschließende Besuch der babylonischen Delegation fanden etwa ein Jahr vor dem Feldzug Sanheribs statt, wie Jes 38,6 zeigt (siehe Fußnote zu Jes 38,1)."] },
      { number: 2, text: "Da drehte sich Hiskija zur Wand und betete:" },
      { number: 3, text: "\"Ach Jahwe, denk doch daran, dass ich dir immer treu war, dass ich mit ganzer Hingabe tat, was dir gefällt!\" Dann begann er laut zu weinen." },
      { number: 4, text: "Jesaja hatte die Innenstadt noch nicht verlassen, da kam das Wort Jahwes zu ihm:" },
      { number: 5, text: "\"Kehr um und sag zu Hiskija, dem Fürsten meines Volkes: 'Jahwe, der Gott deines Vorfahren David, lässt dir sagen: Ich habe dein Gebet gehört und deine Tränen gesehen. Ich werde dich gesund machen. Übermorgen kannst du wieder ins Haus Jahwes gehen." },
      { number: 6, text: "Ich gebe dir noch fünfzehn Jahre Lebenszeit hinzu. Außerdem werde ich dich und diese Stadt vor dem Assyrerkönig retten. Um meiner Ehre willen werde ich Jerusalem beschützen und weil ich es meinem Diener David zugesagt habe.\"" },
      { number: 7, text: "Dann befahl Jesaja: \"Holt einen Brei aus Feigen her!\" Sie brachten ihn und strichen ihn auf das Geschwür. So wurde der König gesund." },
      { number: 8, text: "Hiskija hatte Jesaja noch gefragt: \"An welchem Zeichen kann ich erkennen, dass Jahwe mich wirklich wieder gesund macht und ich übermorgen ins Haus Jahwes gehen kann?\"" },
      { number: 9, text: "Jesaja sagte: \"Jahwe wird dich an folgendem Zeichen erkennen lassen, dass er seine Zusage wahr macht: Soll der Schatten auf der Treppe zehn Stufen vorwärts oder zehn Stufen zurückgehen?\"" },
      { number: 10, text: "Da sagte Hiskija: \"Es ist nichts Besonderes, wenn der Schatten zehn Stufen vorwärts geht. Nein, er soll um zehn Stufen zurückgehen.\"" },
      { number: 11, text: "Da betete der Prophet zu Jahwe, und dieser ließ den Schatten auf der Treppe, die König Ahas gebaut hatte, um zehn Stufen zurückgehen." },
      { number: 12, text: "In dieser Zeit kam eine Gesandtschaft des babylonischen Königs Merodach-Baladan, dem Sohn Baladans*, zu Hiskija. Der König hatte gehört, dass Hiskija krank gewesen war. Er ließ ihm ein Schreiben und Geschenke überbringen.*", heading: "Gesandte aus Babylon", footnotes: ["Sohn Baladans. Regierte von 721-710 v.Chr. über Babylon. Danach musste er sich der assyrischen Herrschaft unter Sargon II. beugen. Einige Zeit nach Sargons Tod, 705 v.Chr., konnte er kurz die babylonische Unabhängigkeit wiederherstellen, bis er 702 v.Chr. vor Sanherib fliehen musste.", "... überbringen. Offenbar wollte Merodach-Baladan Hiskija in eine anti-assyrische Allianz bringen, als er um das Jahr 702 v.Chr. eine Delegation zu Hiskija schickte."] },
      { number: 13, text: "Hiskija freute sich sehr darüber und zeigte ihnen seinen ganzen Besitz: Silber, Gold, die Vorräte an Balsam und feinem Öl, sein Waffenlager und alle seine anderen Schätze. Er zeigte ihnen alles in seinem Haus und in seinem ganzen Reich." },
      { number: 14, text: "Da kam der Prophet Jesaja zu ihm und fragte: \"Was wollten diese Männer von dir? Woher sind sie gekommen?\" – \"Sie kamen aus einem sehr fernen Land\", erwiderte Hiskija, \"aus Babylonien.\"" },
      { number: 15, text: "\"Was haben sie in deinem Palast gesehen?\", fragte Jesaja weiter. \"Sie haben alles gesehen, was ich besitze\", erwiderte Hiskija. \"Ich habe sie in alle Schatzkammern schauen lassen.\"" },
      { number: 16, text: "Da sagte Jesaja: \"Höre, was Jahwe, der allmächtige Gott, dir sagen lässt:" },
      { number: 17, text: "'Eines Tages wird der ganze Reichtum in deinem Palast, alles, was du und deine Vorfahren angehäuft haben, nach Babylon weggeschafft werden. Nichts wird übrig bleiben, spricht Jahwe." },
      { number: 18, text: "Und von deinen Enkelsöhnen, deinen Nachfahren, die du gezeugt haben wirst, wird man einige nach Babylon bringen. Sie werden den König dort in seinem Palast bedienen.'\"" },
      { number: 19, text: "Da sagte Hiskija zu Jesaja: \"Das Wort Jahwes, das du mir gesagt hast, ist gut.\" Und er fügte hinzu: \"Wenn nur zu meinen Lebzeiten Frieden und Sicherheit herrschen!\"" },
      { number: 20, text: "Was sonst noch über Hiskijas Herrschaft zu sagen ist, über seine Taten und Erfolge, wie er den Teich anlegen und die Wasserleitung bauen ließ, um die Stadt mit Wasser zu versorgen, findet man in der Chronik der Könige von Juda." },
      { number: 21, text: "Als Hiskija starb, trat sein Sohn Manasse die Herrschaft an." },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Manasse war zwölf Jahre alt gewesen, als er Mitregent wurde, und regierte insgesamt 55 Jahre* in Jerusalem. Seine Mutter hieß Hefzi-Bah.", heading: "Die bösen Söhne Hiskijas (21)\nManasse von Juda", footnotes: ["55 Jahre. 697-642 v.Chr. Das war die längste Regierungszeit eines Königs im gesamten Israel. Die ersten zehn Jahre bis Hiskijas Tod war er Mitregent."] },
      { number: 2, text: "Er tat, was Jahwe verabscheute, und übernahm die schrecklichen Bräuche der Völker, die Jahwe vor den Israeliten vertrieben hatte." },
      { number: 3, text: "Er baute die Höhenheiligtümer wieder auf, die sein Vater Hiskija zerstört hatte, er ließ Altäre für Baal errichten und ein Pfahlbild der Aschera aufstellen, wie es König Ahab von Israel gemacht hatte. Er warf sich vor dem Heer der Sterne am Himmel nieder und brachte ihm Opfer." },
      { number: 4, text: "Er stellte sogar Altäre im Haus Jahwes auf, von dem Jahwe doch gesagt hatte: \"Dort, in Jerusalem, will ich meinen Namen wohnen lassen.\"" },
      { number: 5, text: "Ja, in den beiden Vorhöfen des Tempels errichtete er Altäre zur Verehrung der Sterne." },
      { number: 6, text: "Einen seiner Söhne verbrannte er als Opfer. Er gab sich mit Zeichendeutung und Wahrsagerei ab, ließ sich mit Toten- und mit Sehergeistern* ein. So tat er vieles, was Jahwe verabscheute, und forderte seinen Zorn heraus.", footnotes: ["... Sehergeistern. Damit verstieß Manasse ausdrücklich gegen das Verbot dieser Dinge in 5. Mose 18,10."] },
      { number: 7, text: "Er stellte das Bild der Göttin Aschera im Tempel auf, von dem Jahwe zu David und seinem Sohn Salomo gesagt hatte: \"In diesem Haus und in Jerusalem, das ich mir aus allen Stämmen Israels ausgesucht habe, soll mein Name für immer wohnen." },
      { number: 8, text: "Ich will die Israeliten nicht mehr aus dem Land vertreiben, das ich ihren Vorfahren gegeben habe, wenn sie mir nur gehorchen und das Gesetz befolgen, das mein Diener Mose ihnen verordnet hat.\"" },
      { number: 9, text: "Aber sie hörten nicht darauf, und Manasse verführte sie, mehr Böses zu tun als die Völker, die Jahwe vor den Israeliten beseitigt hatte." },
      { number: 10, text: "Da ließ Jahwe ihnen durch seine Diener, die Propheten, sagen:" },
      { number: 11, text: "\"Weil König Manasse von Juda diese Gräueltaten verübt und Schlimmeres getan hat als die Amoriter, die früher hier gewohnt haben, und weil er ganz Juda durch seine Mistgötzen zur Sünde verführt hat," },
      { number: 12, text: "darum spricht Jahwe, der Gott Israels: 'Passt auf, ich werde ein Unheil über Juda und Jerusalem bringen, dass es jedem, der davon hört, in den Ohren dröhnt!" },
      { number: 13, text: "Über Jerusalem wird dieselbe Messschnur gespannt wie über Samaria; sein Königshaus wird mit derselben Waage gewogen wie das Haus Ahab. Ich werde Jerusalem auswischen, so wie man eine Schüssel auswischt und umstülpt." },
      { number: 14, text: "Und den Rest, der dann noch übrig geblieben ist, werde ich verstoßen. Ich gebe sie in die Gewalt ihrer Feinde, die sie ausrauben und plündern." },
      { number: 15, text: "Denn von dem Tag an, als ihre Vorfahren aus Ägypten gezogen sind, haben sie Böses getan und meinen Zorn herausgefordert – bis heute.'\"" },
      { number: 16, text: "Manasse ließ auch sehr viele Menschen unschuldig umbringen; Ströme von Blut flossen in Jerusalem.* Das kam noch zu dem Götzendienst hinzu, mit dem er ganz Juda zur Sünde verführte, sodass sie taten, was Jahwe verabscheute.", footnotes: ["Ströme von Blut. Josephus überliefert, dass Manasse täglich Menschen umbrachte. Auch der Prophet Jesaja soll ihm zum Opfer gefallen und in einem hohlen Baum zersägt worden sein, siehe Hebräer 11,37."] },
      { number: 17, text: "Was sonst noch über Manasses Herrschaft, seine Taten und seine Sünde zu sagen ist, findet man in der Chronik der Könige von Juda." },
      { number: 18, text: "Als Manasse starb, wurde er im Garten seines Palastes, dem Garten, der einmal Usa gehört hatte, begraben. Die Herrschaft ging auf seinen Sohn Amon über." },
      { number: 19, text: "Als Amon die Herrschaft antrat, war er 22 Jahre alt. Er regierte zwei Jahre* in Jerusalem. Seine Mutter hieß Meschullemet. Sie war eine Tochter von Haruz aus Jotba.", heading: "Amon von Juda", footnotes: ["zwei Jahre. 642-640 v.Chr."] },
      { number: 20, text: "Wie sein Vater Manasse tat er, was Jahwe verabscheute." },
      { number: 21, text: "In allem folgte er seinem Beispiel. Wie sein Vater opferte er den Götzen und warf sich vor ihnen nieder." },
      { number: 22, text: "Er verließ Jahwe, den Gott seiner Vorfahren, und kümmerte sich nicht um seine Gebote." },
      { number: 23, text: "Einige seiner Hofbeamten verschworen sich gegen ihn und töteten ihn in seinem Haus." },
      { number: 24, text: "Doch das Volk brachte alle Verschwörer um und setzte Amons Sohn Joschija zum König ein." },
      { number: 25, text: "Was sonst noch über Amons Herrschaft zu sagen ist, findet man in der Chronik der Könige von Juda." },
      { number: 26, text: "Man bestattete ihn in seinem Familiengrab im Garten Usas und sein Sohn Joschija trat die Herrschaft an." },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Joschija war bei Herrschaftsantritt acht Jahre alt und regierte 31 Jahre in Jerusalem*. Seine Mutter hieß Jedida. Sie war eine Tochter Adajas und stammte aus Bozkat.", heading: "Der gute König Joschija (22-23)\nJoschija von Juda und das Gesetzbuch", footnotes: ["31 Jahre. 640-609 v.Chr."] },
      { number: 2, text: "Joschija tat, was Jahwe gefiel. Er folgte dem Vorbild seines Vorfahren David und ließ sich durch nichts davon abbringen." },
      { number: 3, text: "In seinem 18. Regierungsjahr* schickte er den Staatsschreiber Schafan Ben-Azalja, den Enkel Meschullams, mit dem folgenden Auftrag in Jahwes Haus:", footnotes: ["18. Regierungsjahr. 622 v.Chr."] },
      { number: 4, text: "\"Geh zum Hohen Priester Hilkija und bitte ihn, das Geld bereitzuhalten, das in den Tempel Jahwes gebracht und von den Torhütern eingesammelt worden ist." },
      { number: 5, text: "Er soll es den Meistern aushändigen, die für die Ausbesserungsarbeiten am Haus Jahwes verantwortlich sind. Diese sollen davon den Lohn für die Handwerker zahlen," },
      { number: 6, text: "für die Zimmerleute, Bauarbeiter und Maurer, und davon auch die Kosten für das Baumaterial begleichen, für das Holz und die behauenen Steine." },
      { number: 7, text: "Die Meister müssen keine Rechenschaft über die Ausgaben ablegen. Man soll auf ihre Ehrlichkeit vertrauen.\"" },
      { number: 8, text: "Als der Staatsschreiber dem Hohen Priester alles ausgerichtet hatte, sagte dieser zu ihm: \"Ich habe die Schriftrolle mit dem Gesetz* im Haus Jahwes gefunden!\" und gab sie ihm. Schafan nahm sie entgegen und las darin.", footnotes: ["Schriftrolle mit dem Gesetz. Hier ist wohl das ganze 5. Buch Mose gemeint, das sich als geschlossenes Bundesgesetz darstellt."] },
      { number: 9, text: "Dann ging er zum König und meldete: \"Deine Diener haben das Geld, das sich im Tempel vorfand, abgepackt und den Meistern ausgehändigt, die für die Ausbesserungsarbeiten am Haus Jahwes verantwortlich sind.\"" },
      { number: 10, text: "Er berichtete dem König auch, dass der Hohe Priester Hilkija ihm eine Schriftrolle gegeben hatte, und las sie dem König vor." },
      { number: 11, text: "Als der König hörte, was in dieser Schriftrolle mit dem Gesetz stand, riss er sein Obergewand ein" },
      { number: 12, text: "und befahl dem Hohen Priester Hilkija, Ahikam Ben-Schafan, Achbor Ben-Michaja, Schafan, dem Staatsschreiber, und Asaja, dem Vertrauten des Königs:" },
      { number: 13, text: "\"Geht und fragt Jahwe um Rat wegen der Worte in dieser Schriftrolle. Fragt ihn für mich, für das Volk und für ganz Juda. Denn Jahwe muss sehr zornig auf uns sein, weil unsere Vorfahren nicht auf die Worte in dieser Schriftrolle gehört und sich nicht nach dem gerichtet haben, was dort für uns geschrieben steht.\"" },
      { number: 14, text: "Da gingen die fünf Männer zu der Prophetin Hulda, die in der Neustadt von Jerusalem wohnte, und redeten mit ihr. Sie war die Frau von Schallum Ben-Tikwa, dem Enkel von Harha, dem Aufseher über die Kleiderkammern." },
      { number: 15, text: "Sie sagte ihnen im Namen Jahwes: \"Richtet dem Mann, der euch zu mir geschickt hat, Folgendes aus:" },
      { number: 16, text: "'So spricht Jahwe: Passt auf, ich werde Unglück über diese Stadt und ihre Bewohner bringen, wie es in der Schriftrolle steht, die der König von Juda gelesen hat." },
      { number: 17, text: "Sie haben mir die Treue gebrochen und anderen Göttern Rauchopfer gebracht. Mit ihren selbst gemachten Götzenbildern haben sie mich zum Zorn gereizt. Mein Grimm hat sich an dieser Stadt entzündet und wird sie verbrennen!'" },
      { number: 18, text: "Doch zum König selbst, der euch hergeschickt hat, um Jahwe zu befragen, sollt ihr sagen: 'So spricht Jahwe, Israels Gott: Du hast die Worte gehört," },
      { number: 19, text: "die ich gegen diese Stadt und ihre Bewohner gerichtet habe, dass sie zu einem abschreckenden Beispiel und zum Fluchwort werden sollen. Doch du hast dich vor mir gebeugt, du hast deine Kleidung eingerissen und vor mir geweint. Darum habe ich dein Gebet erhört, sagt Jahwe." },
      { number: 20, text: "Du wirst in Frieden sterben und im Grab deiner Väter bestattet werden. Du wirst das Unheil, das ich über diese Stadt bringen werde, nicht mit ansehen müssen.'\" Die Abgesandten richteten dem König alles aus." },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Da ließ der König alle Ältesten von Jerusalem und Juda zu sich kommen", heading: "Joschijas Reformen" },
      { number: 2, text: "und ging mit allen Männern von Juda in den Tempel hinauf und mit ihm alle Einwohner Jerusalems, die Priester und Propheten und überhaupt das ganze Volk, klein und groß. Dort ließ er ihnen das ganze Bundesgesetz* vorlesen, das im Haus Jahwes gefunden worden war.", footnotes: ["Bundesgesetz. Die kürzeste Zusammenfassung davon sind die zehn Gebote (5. Mose 5)."] },
      { number: 3, text: "Der König stand auf der obersten Stufe und schloss einen Bund mit Jahwe. Er verpflichtete das ganze Volk, Jahwe nachzufolgen, seine Gebote, Anweisungen und Ordnungen mit ganzem Herzen und ganzer Seele zu befolgen, alles zu erfüllen, was in der Schriftrolle gefordert war. Das ganze Volk trat in den Bund ein." },
      { number: 4, text: "Der König befahl dem Hohen Priester Hilkija, den Oberpriestern und den Torhütern, alle Spuren des Götzendienstes aus dem Tempel zu entfernen. Alle Gegenstände und Einrichtungen, die für den Baal, die Aschera und das Heer der Sterne bestimmt waren, ließ er hinausbringen und außerhalb Jerusalems in den Terrassengärten am Kidrontal verbrennen. Die Asche ließ er nach Bet-El schaffen." },
      { number: 5, text: "Er setzte die Götzenpriester ab, die von den Königen Judas eingesetzt worden waren und in den Höhenheiligtümern der Städte Judas und der Umgebung von Jerusalem Räucheropfer brachten. Er entließ auch alle, die dem Baal, der Sonne, dem Mond, den Tierkreiszeichen und dem ganzen Sternenheer geräuchert hatten." },
      { number: 6, text: "Er schaffte die Aschera aus dem Haus Jahwes hinaus und verbrannte sie im Kidrontal. Die Überreste ließ er zu Staub zerstoßen und auf die Gräber des einfachen Volkes streuen." },
      { number: 7, text: "Er ließ im Tempelgelände die Häuser der Männer abreißen, die sich für den Fruchtbarkeitskult prostituiert hatten. Auch Frauen hatten dort Gewänder für die Aschera gewebt." },
      { number: 8, text: "Joschija ließ alle Priester aus den Städten Judas nach Jerusalem kommen und alle Höhenheiligtümer von Geba bis Beerscheba*, wo sie Räucheropfer dargebracht hatten, entweihen. Er riss auch die Altäre vor dem Tor des Stadtkommandanten Joschua nieder. Sie standen auf der linken Seite, wenn man zum Tor hereinkam.", footnotes: ["Geba lag an der Nordgrenze des damaligen Reiches, Beerscheba an der Südgrenze."] },
      { number: 9, text: "Die Priester der Höhenheiligtümer durften zwar keinen Opferdienst am Altar Jahwes tun, bekamen aber Anteil an den ungesäuerten Broten, die den Priestern zustehen." },
      { number: 10, text: "Der König entweihte auch die Opferstätte des Tofet* im Ben-Hinnom-Tal, damit dort niemand mehr seinen Sohn oder seine Tochter als Opfer für den Moloch verbrennen konnte.", footnotes: ["Tofet bedeutet so viel wie Gräuel oder Gespei."] },
      { number: 11, text: "Außerdem ließ er die Standbilder der Pferde abreißen, die die Könige von Juda zu Ehren der Sonne im Haus Jahwes aufgestellt hatten. Sie standen in den Arkaden beim Dienstraum des Hofbeamten Netan-Melech. Und die dazugehörigen Sonnenwagen ließ er verbrennen." },
      { number: 12, text: "Auch die Altäre, die die Könige von Juda auf dem Dach des von Ahas erbauten Obergeschosses errichtet hatten, und die, die Manasse in den beiden Vorhöfen des Tempels gebaut hatte, ließ der König abbrechen, zertrümmern und ihren Schutt ins Kidrontal werfen." },
      { number: 13, text: "Der König entweihte auch die Höhenheiligtümer, die östlich vor Jerusalem und südlich vom Berg des Verderbens* standen. König Salomo hatte sie einst für Astarte, die Missgestalt der Sidonier*, für Kemosch, das Scheusal der Moabiter, und für Milkom, den Gräuel der Ammoniter*, bauen lassen.", footnotes: ["Berg des Verderbens. Gemeint ist wohl der Ölberg, denn Verderben und Salböl klingen im Hebräischen sehr ähnlich.", "Sidonier waren Einwohner der Stadt Sidon und ihres Herrschaftsbereichs in Phönizien, heute Saida im Libanon.", "Die Moabiter lebten östlich vom Toten Meer und die Ammoniter nordöstlich davon."] },
      { number: 14, text: "Er ließ die Steinmale zerbrechen und die Aschera-Pfähle umhauen. Überall, wo sie gestanden hatten, ließ er Menschenknochen hinwerfen.*", footnotes: ["Menschenknochen hinwerfen. So wurden diese Stätten entweiht."] },
      { number: 15, text: "Auch den Altar in dem Höhenheiligtum Bet-El, das Jerobeam Ben-Nebat gebaut und damit Israel zur Sünde verführt hatte, ließ der König zerstören. Den Altar ließ er abreißen, den Tempel und die Aschera niederbrennen und alles zu Staub zermalmen." },
      { number: 16, text: "Vorher noch hatte er den Altar entweiht. Er hatte sich umgesehen und die Grabhöhlen am Hang entdeckt. Da ließ er die Gebeine herausholen und auf dem Altar verbrennen. So ging das Wort Jahwes in Erfüllung, das der Mann Gottes damals ausrief.*", footnotes: ["damals ausrief. Siehe 1. Könige 13,2. Das Geschehen lag mehr als 300 Jahre zurück."] },
      { number: 17, text: "Der Blick des Königs war gerade auf dessen Grabmal gefallen, und er fragte die Bewohner der Stadt danach. Sie erwiderten: \"Das ist das Grab des Gottesmannes, der aus Juda gekommen ist und genau diese Dinge vorausgesagt hat, die du jetzt mit diesem Altar getan hast.\"" },
      { number: 18, text: "Da befahl der König: \"Lasst ihn ruhen! Niemand soll sich an seinen Gebeinen vergreifen!\" So wurden seine Gebeine verschont,* ebenso die Gebeine des anderen Propheten, der aus Samaria stammte.", footnotes: ["Gebeine verschont. Siehe 1. Könige 13,30-32."] },
      { number: 19, text: "Joschija beseitigte auch alle anderen Höhenheiligtümer der Städte Samarias. Die Könige Israels hatten sie bauen lassen und ihren Gott damit herausgefordert. Er verfuhr mit diesen Heiligtümern genauso wie mit dem in Bet-El." },
      { number: 20, text: "Er ließ ihre Priester auf den Altären abschlachten und außerdem Menschenknochen darauf verbrennen. Daraufhin kehrte er nach Jerusalem zurück." },
      { number: 21, text: "Dann befahl der König dem ganzen Volk: \"Feiert Jahwe, eurem Gott, ein Passafest*, wie es in unserem Bundesbuch beschrieben ist!\"", footnotes: ["Passafest. Siehe 5. Mose 16,1-8."] },
      { number: 22, text: "Denn so war das Fest seit der Zeit der Richter, die Israel angeführt hatten, und die ganze Zeit der Könige Israels und Judas hindurch nicht mehr gefeiert worden." },
      { number: 23, text: "Aber jetzt, im 18. Regierungsjahr* von König Joschija wurde dieses Passa für Jahwe in Jerusalem gefeiert.", footnotes: ["18. Regierungsjahr. 622 v.Chr. Joschija war damals 26 Jahre alt."] },
      { number: 24, text: "Joschija hatte alle Totenbeschwörer und Wahrsager, die Hausgötter und alle anderen Scheusale in Juda und Jerusalem abgeschafft, um alles nach dem Wortlaut des Gesetzes in der Schriftrolle zu erfüllen, die der Priester Hilkija im Haus Jahwes gefunden hatte." },
      { number: 25, text: "Weder vor Joschija noch nach ihm gab es einen König, der mit ganzem Herzen, ganzer Seele und ganzer Kraft zu Jahwe umgekehrt wäre und sich so wie er nach dem ganzen Gesetz Moses richtete." },
      { number: 26, text: "Trotzdem löschte Jahwe die gewaltige Glut seines Zornes über Juda nicht mehr aus. Dieser war wegen der schweren Beleidigungen ausgebrochen, die Manasse ihm zugefügt hatte.", heading: "Das Ende Joschijas" },
      { number: 27, text: "So blieb Jahwe bei seinem Entschluss: \"Auch Juda will ich mir aus den Augen schaffen, wie ich Israel verstoßen habe. Und mit dieser Stadt, die ich erwählt habe, mit Jerusalem, will ich nichts mehr zu tun haben! Ebenso wenig mit dem Haus, von dem ich einst sagte, dass mein Name dort wohnen soll!\"" },
      { number: 28, text: "Was es sonst noch über Joschijas Herrschaft zu berichten gibt, findet man in der Chronik der Könige von Juda." },
      { number: 29, text: "Während seiner Regierungszeit zog Pharao Necho*, der König von Ägypten, mit seinem Heer zum König von Assyrien* an den Euphrat. Doch Joschija stellte sich ihm bei Megiddo entgegen* und wurde gleich zu Beginn des Kampfes getötet.", footnotes: ["Necho II. herrschte von 610-595 v.Chr. über Ägypten.", "zum König von Assyrien. Necho wollte König Assur-Ubalit II., dem letzten assyrischen König, gegen die wachsende babylonische Macht unter Nabopolassar helfen. Das muss im Jahr 609 v.Chr. gewesen sein.", "bei Megiddo entgegen. Wahrscheinlich sperrte Joschija den Pass von Megiddo für die ägyptische Armee."] },
      { number: 30, text: "Seine Diener brachten den toten König auf einem Wagen nach Jerusalem und bestatteten ihn in der vorbereiteten Gruft. Das Volk salbte seinen Sohn Joahas zum König und setzte ihn als Nachfolger ein." },
      { number: 31, text: "Joahas war bei Herrschaftsantritt 23 Jahre alt und regierte drei Monate* in Jerusalem. Seine Mutter hieß Hamutal und war die Tochter von Jirmeja aus Libna.", heading: "Die bösen Söhne Joschijas (23-24)\nJoahas und Jojakim", footnotes: ["drei Monate. Das war 609 v.Chr."] },
      { number: 32, text: "Er tat, was Jahwe verabscheute, genau wie seine Vorfahren." },
      { number: 33, text: "Pharao Necho setzte ihn jedoch ab und nahm ihn in Ribla* in der Provinz Hamat gefangen. Das Land musste einen Tribut von dreieinhalb Tonnen Silber und 34 Kilogramm Gold an ihn zahlen.", footnotes: ["In Ribla am Orontes, etwa 105 km nördlich von Damaskus, hatte Necho sein Hauptquartier aufgeschlagen."] },
      { number: 34, text: "Dann setzte Pharao Necho Eljakim, einen anderen Sohn Joschijas, zum König ein und änderte seinen Namen in Jojakim. Joahas nahm er nach Ägypten mit, wo dieser bis zu seinem Tod blieb." },
      { number: 35, text: "Jojakim lieferte dem Pharao das Silber und Gold ab. Um die verlangte Summe aufbringen zu können, musste er das Land besteuern. Von jedem Einwohner forderte er einen Betrag entsprechend seinem Vermögen." },
      { number: 36, text: "Jojakim war bei Herrschaftsantritt 25 Jahre alt und regierte elf Jahre* in Jerusalem. Seine Mutter hieß Sebuda und war die Tochter von Pedaja aus Ruma*.", footnotes: ["elf Jahre. 609-598 v.Chr.", "Ruma lag 10 km nördlich des späteren Nazaret."] },
      { number: 37, text: "Auch er tat, was Jahwe verabscheute, genau wie seine Vorgänger." },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Während seiner Regierungszeit zog König Nebukadnezzar* von Babylon mit einem Heer heran. Jojakim unterwarf sich ihm.* Drei Jahre später jedoch lehnte er sich gegen ihn auf.*", footnotes: ["Nebukadnezzar war der mächtigste König von Babylon und regierte von 605-562 v.Chr.", "unterwarf sich ihm. Das muss im Jahr 605 v.Chr. gewesen sein und war der Beginn der babylonischen Gefangenschaft der Juden, weil hier schon die ersten Geiseln (unter denen sich auch Daniel befand, siehe Daniel 1,1-3) weggeführt wurden.", "lehnte sich auf. Vielleicht war sein Entschluss davon beeinflusst, dass sich Ägypten 601 v.Chr. erfolgreich gegen Nebukadnezzar verteidigt hatte."] },
      { number: 2, text: "Da ließ Jahwe Räuberbanden der Chaldäer* und solche aus Syrien, Moab und Ammon in Juda einfallen, um es zu Grunde zu richten. So hatte es Jahwe durch seine Propheten, die ihm dienten, angekündigt.", footnotes: ["Die Chaldäer waren aramäisch (syrisch) sprechende Semiten aus dem südlichen Zweistromland."] },
      { number: 3, text: "Ja, das alles geschah ausdrücklich auf den Befehl Jahwes hin, denn er wollte sich die Judäer aus den Augen schaffen. Manasses Sünden und sein ganzes Tun," },
      { number: 4, text: "die vielen unschuldig umgebrachten Menschen, die Ströme von Blut, die in Jerusalem geflossen waren, wollte Jahwe nicht mehr vergeben." },
      { number: 5, text: "Was sonst noch über Jojakims Herrschaft zu sagen ist, findet man in der Chronik der Könige von Juda." },
      { number: 6, text: "Als er starb, wurde sein Sohn Jojachin* König.", footnotes: ["Jojachin wird auch Jechonja (1. Chronik 3,16) und Konja (Jeremia 22,4) genannt."] },
      { number: 7, text: "Zu dieser Zeit wagte es der König von Ägypten nicht mehr, die Grenzen seines Landes zu überschreiten, denn der König von Babylon hatte ihm alle Gebiete vom Bach Ägyptens* bis an den Euphrat abgenommen.", footnotes: ["Nach Josua 15,4war der Bach Ägyptens die Grenze zwischen Israel und Ägypten. Heute: Wadi El-Arisch."] },
      { number: 8, text: "Jojachin war bei Herrschaftsantritt* 18 Jahre alt und regierte drei Monate in Jerusalem. Seine Mutter hieß Nehuschta und war die Tochter Elnatans aus Jerusalem.", heading: "Jojachin von Juda", footnotes: ["Herrschaftsantritt Weil babylonische Schriften den Fall Jerusalems auf den 16. März 597 datieren, muss Jojachin im Dezember 598 König geworden sein."] },
      { number: 9, text: "Er tat, was Jahwe verabscheute, genau wie seine Vorgänger." },
      { number: 10, text: "Damals war das Heer des Königs Nebukadnezzar von Babylon erneut gegen Jerusalem gezogen und hatte die Stadt belagert." },
      { number: 11, text: "Während der Belagerung erschien Nebukadnezzar selbst vor der Stadt." },
      { number: 12, text: "Da ergab sich Jojachin. Zusammen mit seiner Mutter, seinen Beamten, seinen Offizieren und Hofleuten ging er zum König von Babylon hinaus, der ihn sogleich gefangen nahm. Das geschah im achten Regierungsjahr Nebukadnezzars." },
      { number: 13, text: "Und wie Jahwe es angedroht hatte, ließ Nebukadnezzar alle Schätze, die sich im Tempel Jahwes und im Königspalast befanden, wegschaffen und alle goldenen Gegenstände zerschlagen, die König Salomo von Israel für den Tempel hatte anfertigen lassen." },
      { number: 14, text: "Aus Jerusalem führte er alle Offiziere und erfahrenen Soldaten in die Verbannung, alle Bau- und Metallhandwerker, insgesamt zehntausend Mann. Zurück blieb nur das einfache Volk." },
      { number: 15, text: "Auch Jojachin ließ er nach Babylon schaffen, ebenso seine Mutter, seine Frauen, seine Hofleute und die wohlhabenden Bürger des Landes. Sie alle schickte er von Jerusalem in die Verbannung nach Babylonien," },
      { number: 16, text: "dazu siebentausend Soldaten und tausend Bauhandwerker und Schmiede, alle, die mit Waffen umgehen konnten." },
      { number: 17, text: "In Jerusalem setzte er an Jojachins Stelle dessen Onkel Mattanja als König ein und änderte seinen Namen in Zidkija." },
      { number: 18, text: "Als Zidkija die Herrschaft antrat, war er 21 Jahre alt. Er regierte elf Jahre in Jerusalem. Seine Mutter hieß Hamutal; sie war eine Tochter von Jirmeja und stammte aus Libna.", heading: "Zidkija von Juda" },
      { number: 19, text: "Zidkija tat wie Jojakim, was Jahwe verabscheute." },
      { number: 20, text: "Doch jetzt war das Maß voll. Jahwe war so zornig über die Leute von Juda und Jerusalem, dass er sie aus seinen Augen wegschaffen ließ.Dann lehnte sich Zidkija gegen den König von Babylon auf." },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Da zog Nebukadnezzar erneut mit einem Heer gegen Jerusalem und ließ einen Belagerungswall rings um die Stadt aufschütten. Die Belagerung begann im neunten Regierungsjahr Zidkijas, am 10. Januar*,", heading: "Der Weg in die babylonische Gefangenschaft (25)", footnotes: ["Januar. Wörtlich: im 10. Monat. Es war das Jahr 588 v.Chr. Zum Datum siehe unter Schaltmonat im Vorwort des Übersetzers."] },
      { number: 2, text: "und dauerte bis ins elfte Regierungsjahr Zidkijas.*", footnotes: ["Zidkijas. Also von 588-586 v.Chr."] },
      { number: 3, text: "Zuletzt hatte der Hunger in der Stadt überhand genommen. Für das einfache Volk war nichts mehr zu essen da. Am 9. Juli*", footnotes: ["Juli. Wörtlich: des 4. Monats. Die Belagerung dauerte also (mit Unterbrechung, vgl. Jeremia 37,5) zweieinhalb Jahre."] },
      { number: 4, text: "wurde eine Bresche in die Stadtmauer geschlagen. In der Nacht darauf floh der König mit seinen Soldaten durch den Torweg zwischen den beiden Mauern am Königsgarten und durchbrach den Belagerungsring. Er versuchte, in Richtung der Araba* zu entkommen.", footnotes: ["Als Araba wird der Jordangraben bezeichnet, der sich von Nord nach Süd durch ganz Israel zieht, sogar noch über das Tote Meer hinaus bis nach Elat. Er ist zwischen 12,5 und 22,5 km breit und befindet sich fast überall unter dem Meersspiegel, im Toten Meer 394 Meter unter NN."] },
      { number: 5, text: "Doch die chaldäischen Truppen nahmen die Verfolgung auf und holten Zidkija in der Araba bei Jericho* ein.", footnotes: ["bei Jericho. Das war eine Strecke von etwa 25 km bei einem Höhenunterschied von mehr als 1000 Meter."] },
      { number: 6, text: "Sie nahmen den König gefangen und brachten ihn nach Ribla* vor den König von Babylon, der das Urteil über ihn sprach.", footnotes: ["Ribla. Siehe 2. Könige 23,33."] },
      { number: 7, text: "Zidkija musste zusehen, wie seine Söhne abgeschlachtet wurden; dann stach man ihm die Augen aus und brachte ihn in Ketten nach Babylon." },
      { number: 8, text: "Es war das 19. Regierungsjahr des Königs Nebukadnezzar von Babylon. Am 7. August* traf Nebusaradan, der Befehlshaber der königlichen Leibwache, einer der engsten Vertrauten des Königs, in Jerusalem ein.", heading: "Die Zerstörung Jerusalems", footnotes: ["August. Wörtlich: des 5. Monats. Das war etwa einen Monat nach Eroberung der Stadt im Jahr 586 v.Chr."] },
      { number: 9, text: "Er ließ den Tempel Jahwes, den Königspalast und alle großen Häuser niederbrennen." },
      { number: 10, text: "Seine Truppen zerstörten auch die ganze Stadtmauer." },
      { number: 11, text: "Dann ließ Nebusaradan den Rest der Einwohner und alle, die zum König von Babel übergelaufen waren, gefangen nehmen und in die Verbannung führen." },
      { number: 12, text: "Nur einige Leute vom einfachen Volk ließ er zurück, um die Äcker und Weinberge zu bestellen." },
      { number: 13, text: "Die Chaldäer zertrümmerten die beiden Bronzesäulen, die vor dem Haus Jahwes standen, ebenso die Kesselwagen und das bronzene \"Meer\"* und schafften das Metall nach Babylon.", footnotes: ["Meer. Siehe 2. Könige 16,17."] },
      { number: 14, text: "Sie nahmen auch die Töpfe und Schaufeln, die Messer, die Schalen und alle anderen Bronzegegenstände mit, die für den Tempeldienst gebraucht worden waren." },
      { number: 15, text: "Auch die Feuerpfannen und Sprengschalen, überhaupt alles, was aus reinem Gold und Silber war, nahm der Befehlshaber der Leibwache mit." },
      { number: 16, text: "Für die beiden Säulen, das \"Meer\" und die Kesselwagen im Haus Jahwes hatte Salomo eine ungeheure Menge Bronze verarbeitet." },
      { number: 17, text: "Jede der Säulen war neun Meter hoch, und auf jeder ruhte ein Kapitell von anderthalb Meter Höhe*, das ringsum mit einem Gitterwerk und mit Granatäpfeln verziert war, alles aus Bronze.", footnotes: ["anderthalb Meter Höhe. Wörtlich: 3 Ellen. Nach 1. Könige 7,15-22 und Jeremia 52,22 waren die Kapitelle 5 Ellen, also etwa 2,50 Meter hoch. Wenn man diese Angaben und die aus 1. Könige 7 zugrunde legt, betrug das Gewicht jeder Säule insgesamt etwa 40 Tonnen."] },
      { number: 18, text: "Der Befehlshaber der Leibwache ließ den obersten Priester Seraja festnehmen, dazu seinen Stellvertreter Zefanja und die drei für die Torwache verantwortlichen Priester." },
      { number: 19, text: "In der Stadt fanden sich noch der Hofbeamte, der für die Soldaten zuständig gewesen war, fünf Männer, die zu den Vertrauten des Königs gehört hatten, der Beamte, der für die Musterung des Heeres verantwortlich war, und 60 seiner Männer." },
      { number: 20, text: "Nebusaradan, der Befehlshaber der Leibwache, brachte sie nach Ribla zum König von Babel." },
      { number: 21, text: "Dieser ließ sie dort, in der Provinz Hamat, hinrichten. – So wurde das Volk von Juda in die Verbannung geführt." },
      { number: 22, text: "Über den Rest der Bevölkerung von Juda, die Nebukadnezzar im Land übrig gelassen hatte, setzte er Gedalja Ben-Ahikam, den Enkel Schafans, als Statthalter ein.", heading: "Der Statthalter Gedalja" },
      { number: 23, text: "Als nun die Truppenführer, die entkommen waren, davon erfuhren, kamen sie mit ihren Leuten zu Gedalja nach Mizpa*. Es waren Jischmaël Ben-Netanja, Johanan Ben-Kareach, Seraja Ben-Tanhumet aus Netofa und Jaasanja aus Maacha.", footnotes: ["Mizpa liegt 12 km nördlich von Jerusalem."] },
      { number: 24, text: "Gedalja versprach ihnen unter Eid: \"Ihr müsst keine Angst vor den Chaldäern haben. Bleibt im Land und dient dem König von Babylon! Dann wird euch nichts geschehen.\"" },
      { number: 25, text: "Doch im Oktober* kam Jischmaël Ben-Netanja wieder nach Mizpa. Er war der Enkel von Elischama und stammte aus der königlichen Familie und hatte zehn Männer mitgebracht. Sie töteten Gedalja und alle Judäer und Chaldäer, die bei ihm waren.", footnotes: ["im Oktober. Wörtlich: im 7. Monat. Also zwei Monate nach der Tempelzerstörung im Jahr 586 v. Chr."] },
      { number: 26, text: "Daraufhin floh die ganze Bevölkerung Judas, klein und groß, mit den Truppenführern nach Ägypten, denn sie fürchteten die Rache der Chaldäer." },
      { number: 27, text: "In dem Jahr, als Ewil-Merodach König von Babylonien wurde, begnadigte er König Jojachin von Juda und holte ihn aus dem Gefängnis. Das geschah im 37. Jahr der Gefangenschaft Jojachins, am 27. März*.", heading: "Jojachins Begnadigung", footnotes: ["März. Wörtlich: des 12. Monats. Es war im Jahr 561 v. Chr."] },
      { number: 28, text: "Er behandelte ihn freundlich und gab ihm eine Ehrenstellung unter den Königen, die nach Babylon gebracht worden waren." },
      { number: 29, text: "Jojachin durfte seine Gefängniskleidung ablegen und zeitlebens an der Tafel des Königs speisen." },
      { number: 30, text: "Der König sorgte auch sonst für seinen Unterhalt. Bis zu seinem Lebensende bekam er täglich, was er brauchte." },
    ] },
  ],
};